// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {PancakeV1InfinityHook} from "../PancakeV1InfinityHook.sol";
import {IPancakeV1CLPoolManager} from "../PancakeV1InfinityHookTypes.sol";

interface IBnbAdapterBinding {
    function hook() external view returns (address);
    function poolManager() external view returns (address);
}

/// @notice BNB candidate. Arbitrary lockers cannot evade deferred output fees.
/// Frozen adapter hashes must be obtained from the reviewed compiler build,
/// never from an untrusted adapter's self-reported identity.
contract BnbInfinityHook is PancakeV1InfinityHook {
    mapping(address => bytes32) public adapterHash;
    bool public adaptersFrozen;

    constructor(IPancakeV1CLPoolManager manager, address admin, address protocol)
        PancakeV1InfinityHook(manager, address(0), admin, protocol) {
        require(block.chainid == 56, "BNB_ONLY");
        require(address(manager) == 0xa0FfB9c1CE1Fe56963B0321B32E7A0302114058b, "BNB_MANAGER");
    }

    function attestAdapters(address[] calldata adapters, bytes32[] calldata hashes) external onlyOwner {
        if (adaptersFrozen || adapters.length == 0 || adapters.length > 8
            || adapters.length != hashes.length) revert InvalidPolicy();
        for (uint256 i; i < adapters.length; ++i) {
            address a = adapters[i];
            if (a.code.length == 0 || a.codehash != hashes[i] || adapterHash[a] != bytes32(0)
                || IBnbAdapterBinding(a).hook() != address(this)
                || IBnbAdapterBinding(a).poolManager() != address(poolManager)) revert InvalidPolicy();
            adapterHash[a] = hashes[i];
        }
        adaptersFrozen = true;
    }

    function _authorizeAdapter(address adapter) internal view override {
        if (!adaptersFrozen || adapterHash[adapter] == bytes32(0)
            || adapter.codehash != adapterHash[adapter]) revert InvalidPolicy();
    }
}

contracts/pancake-v1/bnb/BnbInfinityLaun.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {PancakeV1InfinityLaunchEngine} from "../PancakeV1InfinityLaunchEngine.sol";
import {PancakeV1FeeSharingVault} from "../PancakeV1FeeSharingVault.sol";
import {V1PoolId} from "../PancakeV1Interfaces.sol";
import {IInfinityNftModule} from "../PancakeV1LaunchpadInfinityNftUpgradeable.sol";

interface IBnbGraph {
    function launchpad() external view returns (address);
    function engine() external view returns (address);
}

/// @notice Fresh BNB UUPS entrypoint, NOT an upgrade for a Robinhood proxy.
/// Standard and upgradeable NFT rewards share this entrypoint and protocol vault.
/// No no-hook, V1/V2, oracle, USDG, or Robinhood entrypoints are inherited.
contract BnbInfinityLaunchpad is OwnableUpgradeable, UUPSUpgradeable {
    using SafeERC20 for IERC20;
    struct PoolRecord {
        address quoteToken; uint16 weightBps; V1PoolId poolId; uint256 positionId;
        uint256 projectAmount; int24 tickLower; int24 tickUpper; uint256 quotePriceE8; uint8 quoteDecimals;
    }
    struct Allocation { address quoteToken; uint16 weightBps; }
    struct Params {
        bytes identityData; Allocation[] allocations; bytes[] openingData;
        uint256 deadline; bytes32 userSalt; bool sniperProtection; uint256 protectionBlocks;
        uint8 mode; uint16 feeBps; bytes modeData; uint64 policyEffectiveAt; address[] holderExcluded;
    }

    mapping(address => PoolRecord[]) private _pools;
    uint256 public launchFee;
    address public launchFeeRecipient;
    address public socialVerifier;
    address public infinityEngine;
    IInfinityNftModule public nftModule;
    address public directQuoteCoordinator;
    address public nftDirectQuoteCoordinator;
    bool public graphFrozen;
    bool public paused;
    uint256 private _entered;

    error InvalidConfiguration();
    error Unavailable();
    event GraphFrozen(address engine, address nftModule);
    event PauseChanged(bool paused);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }
    function initialize(address admin, address treasury, address verifier, uint256 fee) external initializer {
        if (block.chainid != 56 || admin == address(0) || treasury == address(0)
            || verifier == address(0)) revert InvalidConfiguration();
        __Ownable_init(admin);
        launchFee = fee; launchFeeRecipient = treasury; socialVerifier = verifier;
        paused = true;
    }
    function _authorizeUpgrade(address) internal override onlyOwner {}
    function poolManager() external pure returns (address) {
        return 0xa0FfB9c1CE1Fe56963B0321B32E7A0302114058b;
    }
    function pools(address token) external view returns (PoolRecord[] memory) { return _pools[token]; }

    /// Bind only after reciprocal factory/hook/adapters have been frozen.
    function finalizeGraph(address engine, IInfinityNftModule module,
        address direct, address nftDirect) external onlyOwner {
        if (graphFrozen || engine.code.length == 0
            || !PancakeV1InfinityLaunchEngine(engine).validateLaunchpad(address(this))
            || direct.code.length == 0 || IBnbGraph(direct).launchpad() != address(this))
            revert InvalidConfiguration();
        if (address(module) != address(0)) {
            if (address(module).code.length == 0 || module.launchpad() != address(this)
                || nftDirect.code.length == 0 || IBnbGraph(nftDirect).launchpad() != address(this)
                || IBnbGraph(nftDirect).engine() != address(module)) revert InvalidConfiguration();
        } else if (nftDirect != address(0)) revert InvalidConfiguration();
        infinityEngine = engine; nftModule = module; directQuoteCoordinator = direct;
        nftDirectQuoteCoordinator = nftDirect; graphFrozen = true;
        emit GraphFrozen(engine, address(module));
    }
    function setPaused(bool value) external onlyOwner {
        if (!value && !graphFrozen) revert InvalidConfiguration();
        paused = value; emit PauseChanged(value);
    }
    modifier available() {
        if (paused || !graphFrozen || _entered != 0) revert Unavailable();
        _entered = 1; _; _entered = 0;
    }
    function _validate(bytes memory encoded) private view returns (uint8 mode) {
        Params memory p = abi.decode(encoded, (Params));
        if (keccak256(encoded) != keccak256(abi.encode(p)) || p.mode > 5
            || p.sniperProtection || p.protectionBlocks != 0 || p.policyEffectiveAt != 0
            || p.deadline < block.timestamp || p.deadline > type(uint48).max)
            revert InvalidConfiguration();
        if (p.mode == 3) {
            (, address verifier) = abi.decode(p.modeData, (PancakeV1FeeSharingVault.Recipient[], address));
            if (verifier != socialVerifier) revert InvalidConfiguration();
        }
        if (p.mode == 5 && address(nftModule) == address(0)) revert Unavailable();
        return p.mode;
    }
    function launchInfinity(bytes calldata encoded) external payable available returns (address token) {
        token = _launch(msg.sender, encoded);
    }
    function launchInfinityFor(address creator, bytes calldata encoded)
        external payable available returns (address token) {
        if (msg.sender != directQuoteCoordinator || creator == address(0) || _validate(encoded) == 5)
            revert InvalidConfiguration();
        token = _launch(creator, encoded);
    }
    function launchInfinityNftFor(address creator, bytes calldata encoded)
        external payable available returns (address token) {
        if (msg.sender != nftDirectQuoteCoordinator || creator == address(0) || _validate(encoded) != 5)
            revert InvalidConfiguration();
        token = _launch(creator, encoded);
    }
    function _launch(address creator, bytes memory encoded) private returns (address token) {
        if (_validate(encoded) == 5) return nftModule.launch{value: msg.value}(creator, encoded);
        return PancakeV1InfinityLaunchEngine(infinityEngine).launch{value: msg.value}(creator, encoded);
    }
    function launchInfinityAndBuy(bytes calldata encoded)
        external payable available returns (address token, uint256 output) {
        (bytes memory launchData,) = abi.decode(encoded, (bytes, bytes));
        // Buy-only operation is deliberately not a launch entrypoint.
        if (launchData.length == 0) revert InvalidConfiguration();
        if (_validate(launchData) == 5) return nftModule.launchAndBuy{value: msg.value}(msg.sender, encoded);
        return PancakeV1InfinityLaunchEngine(infinityEngine).launchAndBuy{value: msg.value}(msg.sender, encoded);
    }
    function recordInfinityPool(address token, address quote, bytes32 id, uint16 weight) external {
        if (msg.sender != infinityEngine || _entered == 0 || _pools[token].length >= 5)
            revert InvalidConfiguration();
        _pools[token].push(PoolRecord(quote, weight, V1PoolId.wrap(id), 0, 0, 0, 0, 0, 0));
    }
    function releaseInfinityNftSupply(address project) external {
        if (msg.sender != address(nftModule) || _entered == 0 || !nftModule.validateSupply(project))
            revert InvalidConfiguration();
        uint256 amount = 1_000_000_000 ether;
        if (IERC20(project).balanceOf(address(this)) != amount || IERC20(project).totalSupply() != amount)
            revert InvalidConfiguration();
        IERC20(project).safeTransfer(msg.sender, amount);
    }
    function recordInfinityNftPool(address project, address quote, bytes32 id, uint16 weight,
        uint256 positionId, uint256 amount, int24 lower, int24 upper, uint256 price, uint8 decimals) external {
        if (msg.sender != address(nftModule) || _entered == 0 || _pools[project].length >= 5
            || !nftModule.validatePool(project, quote, id, weight, positionId, amount, lower, upper, price, decimals))
            revert InvalidConfiguration();
        _pools[project].push(PoolRecord(quote, weight, V1PoolId.wrap(id), positionId, amount, lower, upper, price, decimals));
    }
}

contracts/pancake-v1/bnb/BnbInfinityNati.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {PancakeV1InfinitySwapAdapter} from "../PancakeV1InfinitySwapAdapter.sol";
import {IPancakeV1CLPoolManager, IPancakeV1Hooks, PancakeV1PoolKey, PancakeV1Currency} from "../PancakeV1InfinityHookTypes.sol";
import {IPancakeV1InfinityBuySource, IPancakeV1InfinityFeeView} from "../PancakeV1InfinityDeveloperBuyExecutor.sol";
import {V1PoolId} from "../PancakeV1Interfaces.sol";

interface IWBNB is IERC20 { function deposit() external payable; }
interface IBnbV3Router {
    struct ExactInputParams { bytes path; address recipient; uint256 deadline; uint256 amountIn; uint256 amountOutMinimum; }
    function exactInput(ExactInputParams calldata) external payable returns (uint256);
}
interface IBnbV3Factory { function getPool(address, address, uint24) external view returns (address); }

/// @notice Typed native BNB funding. No ETH/USDG intermediary, arbitrary router
/// calldata, or inferred route authority. Partial fills revert atomically.
contract BnbInfinityNativeBuyExecutor {
    using SafeERC20 for IERC20;
    address public constant WBNB = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c;
    address public constant V3_ROUTER = 0x1b81D678ffb9C0263b24A97847620C99d213eB14;
    address public constant V3_FACTORY = 0x0BFbCF9fa4f9C56B0F40a671Ad40E0805A091865;
    bytes32 public constant ROUTE_POLICY_ID = keccak256("pair-bnb-infinity-native-v1");
    address public immutable launchpad;
    address public immutable binder;
    address public engine;
    IPancakeV1CLPoolManager public immutable poolManager;
    IPancakeV1InfinityFeeView public immutable hook;
    PancakeV1InfinitySwapAdapter public immutable adapter;
    mapping(address => uint24) public routeFee;
    bool public routesFrozen;
    uint256 private entered;
    struct BuyPlan {
        uint8 version; address recipient; uint256 totalProjectMinimum;
        uint256[] projectMinimums; uint256[] quoteMinimums; uint256 deadline; bytes32 routePolicyId;
    }
    error InvalidBuy();
    error Residual();

    constructor(address launchpad_, IPancakeV1InfinityFeeView hook_, address expectedEngine) {
        if (block.chainid != 56 || launchpad_.code.length == 0 || address(hook_).code.length == 0)
            revert InvalidBuy();
        launchpad = launchpad_; binder = msg.sender; hook = hook_;
        engine = expectedEngine;
        poolManager = IPancakeV1CLPoolManager(0xa0FfB9c1CE1Fe56963B0321B32E7A0302114058b);
        adapter = new PancakeV1InfinitySwapAdapter(poolManager, IPancakeV1Hooks(address(hook_)));
    }
    /// Freeze only independently reviewed, liquid WBNB -> quote Pancake V3 pools.
    function bind(address engine_, address[] calldata quotes, uint24[] calldata fees) external {
        if (msg.sender != binder || routesFrozen || engine_.code.length == 0
            || (engine != address(0) && engine != engine_)
            || quotes.length != fees.length || quotes.length > 8) revert InvalidBuy();
        for (uint256 i; i < quotes.length; ++i) {
            if (quotes[i] == WBNB || quotes[i] == address(0) || routeFee[quotes[i]] != 0
                || fees[i] == 0 || IBnbV3Factory(V3_FACTORY).getPool(WBNB, quotes[i], fees[i]).code.length == 0)
                revert InvalidBuy();
            routeFee[quotes[i]] = fees[i];
        }
        engine = engine_; routesFrozen = true;
    }
    function execute(address project, address payer, uint256 launchDeadline, bytes calldata encoded)
        external payable returns (uint256 received) {
        BuyPlan memory p = abi.decode(encoded, (BuyPlan));
        if (msg.sender != engine || !routesFrozen || entered != 0 || msg.value == 0
            || project == address(0) || payer == address(0) || p.recipient != payer || p.version != 1
            || p.routePolicyId != ROUTE_POLICY_ID || p.totalProjectMinimum == 0
            || p.deadline < block.timestamp || p.deadline > launchDeadline
            || keccak256(encoded) != keccak256(abi.encode(p))) revert InvalidBuy();
        entered = 1;
        IPancakeV1InfinityBuySource.PoolRecord[] memory pools = IPancakeV1InfinityBuySource(launchpad).pools(project);
        if (pools.length == 0 || pools.length > 5 || p.projectMinimums.length != pools.length
            || p.quoteMinimums.length != pools.length) revert InvalidBuy();
        uint256 baseline = IERC20(WBNB).balanceOf(address(this));
        IWBNB(WBNB).deposit{value: msg.value}();
        if (IERC20(WBNB).balanceOf(address(this)) != baseline + msg.value) revert Residual();
        uint256 beforeOutput = IERC20(project).balanceOf(payer);
        uint256 allocated; uint256 weights;
        for (uint256 i; i < pools.length; ++i) {
            weights += pools[i].weightBps;
            uint256 leg = i + 1 == pools.length ? msg.value - allocated : msg.value * pools[i].weightBps / 10_000;
            allocated += leg;
            if (leg == 0 || pools[i].weightBps == 0 || p.projectMinimums[i] == 0 || p.quoteMinimums[i] == 0)
                revert InvalidBuy();
            uint256 gross = _fund(pools[i].quoteToken, leg, p.quoteMinimums[i], p.deadline);
            _buy(project, pools[i].quoteToken, gross, payer, p.projectMinimums[i], p.deadline,
                V1PoolId.unwrap(pools[i].poolId), i);
        }
        received = IERC20(project).balanceOf(payer) - beforeOutput;
        if (weights != 10_000 || allocated != msg.value || received < p.totalProjectMinimum
            || IERC20(WBNB).balanceOf(address(this)) != baseline) revert Residual();
        entered = 0;
    }
    function _fund(address quote, uint256 amount, uint256 floor, uint256 deadline) private returns (uint256 gross) {
        if (quote == WBNB) {
            if (amount < floor) revert InvalidBuy();
            return amount;
        }
        uint24 fee = routeFee[quote];
        if (fee == 0) revert InvalidBuy();
        uint256 beforeQuote = IERC20(quote).balanceOf(address(this));
        uint256 beforeWbnb = IERC20(WBNB).balanceOf(address(this));
        IERC20(WBNB).forceApprove(V3_ROUTER, amount);
        gross = IBnbV3Router(V3_ROUTER).exactInput(
            IBnbV3Router.ExactInputParams(abi.encodePacked(WBNB, fee, quote), address(this), deadline, amount, floor));
        IERC20(WBNB).forceApprove(V3_ROUTER, 0);
        if (gross < floor || IERC20(quote).balanceOf(address(this)) - beforeQuote != gross
            || beforeWbnb - IERC20(WBNB).balanceOf(address(this)) != amount
            || IERC20(WBNB).allowance(address(this), V3_ROUTER) != 0) revert Residual();
    }
    function _buy(address project, address quote, uint256 gross, address recipient,
        uint256 floor, uint256 deadline, bytes32 id, uint256 index) private {
        bool project0 = project < quote;
        PancakeV1PoolKey memory key = PancakeV1PoolKey(
            PancakeV1Currency.wrap(project0 ? project : quote), PancakeV1Currency.wrap(project0 ? quote : project),
            IPancakeV1Hooks(address(hook)), poolManager, 10_000,
            bytes32(uint256(hook.getHooksRegistrationBitmap()) | (uint256(200) << 16)));
        if (keccak256(abi.encode(key)) != id) revert InvalidBuy();
        uint256 net = gross;
        for (uint256 i; i < 256; ++i) {
            uint256 fee = hook.quoteInputFee(project, net);
            if (fee >= gross) revert InvalidBuy();
            uint256 next = gross - fee;
            if (next == net) break;
            net = next;
        }
        if (net + hook.quoteInputFee(project, net) != gross) revert InvalidBuy();
        uint256 beforeQuote = IERC20(quote).balanceOf(address(this));
        IERC20(quote).forceApprove(address(adapter), gross);
        adapter.executeExactInput(key, !project0, net, gross, floor, address(this), recipient, deadline,
            abi.encode(uint8(1), id, index));
        IERC20(quote).forceApprove(address(adapter), 0);
        if (beforeQuote - IERC20(quote).balanceOf(address(this)) != gross
            || IERC20(quote).allowance(address(this), address(adapter)) != 0) revert Residual();
    }
}

