// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";

/// @notice Direct final vault for up to five wallet or social recipients.
/// @dev Social identities are opaque provider-scoped keys. The verifier binds
/// an identity to a wallet only at claim time; the vault never calls a social API.
contract PancakeV1FeeSharingVault {
    using SafeERC20 for IERC20;

    uint16 public constant BPS = 10_000;
    uint16 public constant MAX_FEE_BPS = BPS;
    uint8 public constant MAX_RECIPIENTS = 5;
    uint8 public constant MAX_EPOCHS = 64;
    bytes32 public constant CLAIM_TYPEHASH = keccak256(
        "Claim(bytes32 provider,bytes32 identityHash,address wallet,bytes32 assetsHash,uint256 nonce,uint256 deadline)"
    );
    bytes32 private constant DOMAIN_TYPEHASH = keccak256(
        "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
    );
    enum Kind { Wallet, Social }
    struct Recipient {
        Kind kind;
        address wallet;
        bytes32 provider;
        bytes32 identityHash;
        uint16 shareBps;
    }
    struct Policy { uint64 activatesAt; uint16 feeBps; uint8 count; }
    address public immutable projectToken;
    address public immutable hook;
    address public immutable admin;
    address public immutable verifier;
    bytes32 private immutable _domainName;
    bytes32 private immutable _domainVersion;
    uint64 public activeEpoch;
    mapping(uint64 => Policy) public policies;
    mapping(uint64 => Recipient[5]) private _recipients;
    mapping(bytes32 => bool) public knownIdentity;
    mapping(uint64 => mapping(address => mapping(address => uint256))) public walletClaimable;
    mapping(uint64 => mapping(bytes32 => mapping(address => uint256))) public socialClaimable;
    mapping(bytes32 => uint256) public nonces;
    mapping(address => uint256) public accrued;
    mapping(address => uint256) public claimed;

    error OnlyHook();
    error OnlyAdmin();
    error InvalidConfiguration();
    error InvalidAuthorization();
    error ExpiredAuthorization();
    error NoClaim();
    error InsufficientRecordedBalance();

    event PolicyAppended(uint64 indexed epoch, uint64 activatesAt, uint16 feeBps);
    event FeeRecorded(uint64 indexed epoch, address indexed asset, uint256 amount);
    event FeeClaimed(address indexed recipient, address indexed asset, uint256 amount);
    event SocialClaimed(
        bytes32 indexed provider, bytes32 indexed identityHash, address indexed wallet,
        address asset, uint256 amount, uint256 nonce
    );

    modifier onlyAdmin() {
        if (msg.sender != admin) revert OnlyAdmin();
        _;
    }

    constructor(address project_, address hook_, address admin_, address verifier_,
        Recipient[] memory recipients_, uint16 feeBps_) {
        if (project_ == address(0) || hook_ == address(0) || admin_ == address(0)
            || verifier_ == address(0) || recipients_.length == 0 || recipients_.length > MAX_RECIPIENTS
            || feeBps_ > MAX_FEE_BPS) revert InvalidConfiguration();
        projectToken = project_;
        hook = hook_;
        admin = admin_;
        verifier = verifier_;
        _domainName = keccak256("PAIR Pancake V1 Fee Sharing");
        _domainVersion = keccak256("1");
        _append(0, recipients_, feeBps_);
    }

    function recipientCount(uint64 epoch) external view returns (uint256) { return policies[epoch].count; }
    function recipient(uint64 epoch, uint256 index) external view returns (Recipient memory) {
        return _recipients[epoch][index];
    }
    function policy(uint64 epoch) external view returns (Policy memory) { return policies[epoch]; }
    function identityNonce(bytes32 provider, bytes32 identityHash) external view returns (uint256) {
        return nonces[_identityKey(provider, identityHash)];
    }

    function appendPolicy(Recipient[] calldata recipients_, uint16 feeBps_, uint64 activatesAt)
        external onlyAdmin {
        // A matured queued policy must become the active epoch before selecting
        // the next slot, otherwise a second append could overwrite it.
        _sync();
        if (activeEpoch >= MAX_EPOCHS || policies[activeEpoch + 1].count != 0) revert InvalidConfiguration();
        if (feeBps_ > MAX_FEE_BPS || recipients_.length == 0 || recipients_.length > MAX_RECIPIENTS) {
            revert InvalidConfiguration();
        }
        if (activatesAt < policies[activeEpoch].activatesAt) revert InvalidConfiguration();
        _append(activatesAt, recipients_, feeBps_);
    }

    function _append(uint64 activatesAt, Recipient[] memory recipients_, uint16 feeBps_) private {
        uint64 epoch = uint64(activeEpoch + 1);
        uint256 total;
        for (uint256 i; i < recipients_.length; ++i) {
            Recipient memory r = recipients_[i];
            bytes32 key = _validateRecipient(r);
            if (_hasDuplicate(recipients_, i, r.kind, key)) revert InvalidConfiguration();
            if (r.kind == Kind.Social) knownIdentity[key] = true;
            _recipients[epoch][i] = r;
            total += r.shareBps;
        }
        if (total != BPS) revert InvalidConfiguration();
        policies[epoch] = Policy(activatesAt, feeBps_, uint8(recipients_.length));
        if (activatesAt <= block.timestamp) activeEpoch = epoch;
        emit PolicyAppended(epoch, activatesAt, feeBps_);
    }

    function _validateRecipient(Recipient memory r) private pure returns (bytes32 key) {
        if (r.kind == Kind.Wallet) {
            if (r.wallet == address(0) || r.shareBps == 0) revert InvalidConfiguration();
            return bytes32(uint256(uint160(r.wallet)));
        }
        key = _identityKey(r.provider, r.identityHash);
        if (r.shareBps == 0) revert InvalidConfiguration();
    }

    function _hasDuplicate(Recipient[] memory recipients_, uint256 index, Kind kind, bytes32 key)
        private pure returns (bool) {
        for (uint256 j; j < index; ++j) {
            Recipient memory prior = recipients_[j];
            bytes32 priorKey = prior.kind == Kind.Wallet
                ? bytes32(uint256(uint160(prior.wallet)))
                : keccak256(abi.encode(prior.provider, prior.identityHash));
            if (prior.kind == kind && priorKey == key) return true;
        }
        return false;
    }

    function _sync() private returns (uint64 epoch) {
        epoch = activeEpoch;
        uint64 next = epoch + 1;
        while (next <= MAX_EPOCHS && policies[next].count != 0 && policies[next].activatesAt <= block.timestamp) {
            epoch = next++;
        }
        activeEpoch = epoch;
    }

    function currentPolicy() external view returns (uint64 epoch, uint16 feeBps) {
        epoch = activeEpoch;
        uint64 next = epoch + 1;
        while (next <= MAX_EPOCHS && policies[next].count != 0 && policies[next].activatesAt <= block.timestamp) ++next;
        return (next - 1, policies[next - 1].feeBps);
    }

    function recordFee(address asset, uint256 amount) external {
        if (msg.sender != hook) revert OnlyHook();
        if (asset == address(0) || amount == 0) revert InvalidConfiguration();
        uint256 outstanding = accrued[asset] - claimed[asset];
        if (IERC20(asset).balanceOf(address(this)) < outstanding + amount) revert InsufficientRecordedBalance();
        uint64 epoch = _sync();
        Policy memory p = policies[epoch];
        uint256 allocated;
        for (uint256 i; i < p.count; ++i) {
            Recipient memory r = _recipients[epoch][i];
            uint256 share = i + 1 == p.count ? amount - allocated : amount * r.shareBps / BPS;
            allocated += share;
            if (r.kind == Kind.Wallet) walletClaimable[epoch][r.wallet][asset] += share;
            else socialClaimable[epoch][_identityKey(r.provider, r.identityHash)][asset] += share;
        }
        accrued[asset] += amount;
        emit FeeRecorded(epoch, asset, amount);
    }

    function claimWallet(address[] calldata assets) external returns (uint256 total) {
        if (assets.length == 0 || assets.length > 20) revert InvalidConfiguration();
        for (uint256 a; a < assets.length; ++a) {
            address asset = assets[a];
            if (asset == address(0)) revert InvalidConfiguration();
            uint256 amount = _takeWallet(msg.sender, asset);
            if (amount != 0) {
                claimed[asset] += amount;
                IERC20(asset).safeTransfer(msg.sender, amount);
                emit FeeClaimed(msg.sender, asset, amount);
                total += amount;
            }
        }
        if (total == 0) revert NoClaim();
    }

    function claimSocial(bytes32 provider, bytes32 identityHash, address wallet, address[] calldata assets,
        uint256 deadline, bytes calldata signature) external returns (uint256 total) {
        bytes32 identityKey = _identityKey(provider, identityHash);
        if (!knownIdentity[identityKey] || wallet == address(0) || assets.length == 0 || assets.length > 20) {
            revert InvalidConfiguration();
        }
        if (block.timestamp > deadline) revert ExpiredAuthorization();
        uint256 nonce = _consumeAuthorization(provider, identityHash, wallet, assets, deadline, signature);
        for (uint256 a; a < assets.length; ++a) {
            address asset = assets[a];
            uint256 amount = _takeSocial(identityKey, asset);
            if (amount != 0) {
                claimed[asset] += amount;
                IERC20(asset).safeTransfer(wallet, amount);
                emit SocialClaimed(provider, identityHash, wallet, asset, amount, nonce);
                total += amount;
            }
        }
        if (total == 0) revert NoClaim();
    }

    function _consumeAuthorization(bytes32 provider, bytes32 identityHash, address wallet, address[] calldata assets,
        uint256 deadline, bytes calldata signature) private returns (uint256 nonce) {
        bytes32 identityKey = _identityKey(provider, identityHash);
        nonce = nonces[identityKey];
        bytes32 assetsHash = keccak256(abi.encode(assets));
        bytes32 structHash = keccak256(
            abi.encode(CLAIM_TYPEHASH, provider, identityHash, wallet, assetsHash, nonce, deadline)
        );
        bytes32 digest = keccak256(abi.encodePacked("\x19\x01", _domainSeparator(), structHash));
        if (ECDSA.recover(digest, signature) != verifier) revert InvalidAuthorization();
        nonces[identityKey] = nonce + 1;
    }

    function _takeWallet(address wallet, address asset) private returns (uint256 amount) {
        for (uint64 e = 1; e <= MAX_EPOCHS; ++e) {
            amount += walletClaimable[e][wallet][asset];
            walletClaimable[e][wallet][asset] = 0;
        }
    }

    function _takeSocial(bytes32 identityKey, address asset) private returns (uint256 amount) {
        for (uint64 e = 1; e <= MAX_EPOCHS; ++e) {
            amount += socialClaimable[e][identityKey][asset];
            socialClaimable[e][identityKey][asset] = 0;
        }
    }

    function _identityKey(bytes32 provider, bytes32 identityHash) private pure returns (bytes32) {
        if (provider == bytes32(0) || identityHash == bytes32(0)) revert InvalidConfiguration();
        return keccak256(abi.encode(provider, identityHash));
    }

    function _domainSeparator() private view returns (bytes32) {
        return keccak256(abi.encode(DOMAIN_TYPEHASH, _domainName, _domainVersion, block.chainid, address(this)));
    }
}

contracts/pancake-v1/PancakeV1HolderDist.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/// @notice Keeperless cumulative quote-fee distribution for a PAIR token.
/// @dev The project token must call checkpoint before each balance update.
contract PancakeV1HolderDistributionVault {
    using SafeERC20 for IERC20;

    uint256 public constant MAGNITUDE = 2 ** 128;
    uint256 public constant MAX_ASSETS = 5;
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    address public immutable projectToken;
    address public immutable hook;
    address public immutable registrar;
    mapping(address => bool) public excluded;
    address[] private _assets;
    mapping(address => bool) public registeredAsset;
    uint256 public eligibleSupply;
    mapping(address => uint256) public magnifiedFeePerShare;
    mapping(address => uint256) public magnifiedRemainder;
    mapping(address => uint256) public pending;
    mapping(address => uint256) public accrued;
    mapping(address => uint256) public claimed;
    mapping(address => mapping(address => int256)) private _correction;
    mapping(address => mapping(address => uint256)) public withdrawn;

    error OnlyHook();
    error OnlyRegistrar();
    error OnlyProjectToken();
    error InvalidConfiguration();
    error NoClaim();
    error InsufficientRecordedBalance();

    event AssetRegistered(address indexed asset);
    event FeeRecorded(address indexed asset, uint256 amount, uint256 eligibleSupply);
    event Checkpoint(address indexed from, address indexed to, uint256 amount, uint256 eligibleSupply);
    event FeeClaimed(address indexed holder, address indexed asset, uint256 amount);

    constructor(address project_, address hook_, address registrar_, address[] memory excluded_) {
        if (project_ == address(0) || hook_ == address(0) || registrar_ == address(0) || excluded_.length > 32) {
            revert InvalidConfiguration();
        }
        projectToken = project_;
        hook = hook_;
        registrar = registrar_;
        excluded[address(0)] = true;
        excluded[address(this)] = true;
        excluded[DEAD] = true;
        for (uint256 i; i < excluded_.length; ++i) {
            if (excluded_[i] == address(0) || excluded_[i] == project_ || excluded[excluded_[i]]) {
                revert InvalidConfiguration();
            }
            excluded[excluded_[i]] = true;
        }
    }

    function assetCount() external view returns (uint256) { return _assets.length; }
    function assetAt(uint256 index) external view returns (address) { return _assets[index]; }

    function registerAsset(address asset) external {
        if (msg.sender != registrar && msg.sender != hook) revert OnlyRegistrar();
        if (asset == address(0) || registeredAsset[asset] || _assets.length >= MAX_ASSETS) {
            revert InvalidConfiguration();
        }
        registeredAsset[asset] = true;
        _assets.push(asset);
        emit AssetRegistered(asset);
    }

    function recordFee(address asset, uint256 amount) external {
        if (msg.sender != hook) revert OnlyHook();
        if (!registeredAsset[asset] || amount == 0) revert InvalidConfiguration();
        uint256 outstanding = accrued[asset] - claimed[asset];
        if (IERC20(asset).balanceOf(address(this)) < outstanding + amount) {
            revert InsufficientRecordedBalance();
        }
        accrued[asset] += amount;
        if (eligibleSupply == 0) pending[asset] += amount;
        else _distribute(asset, amount);
        emit FeeRecorded(asset, amount, eligibleSupply);
    }

    function checkpoint(address from, address to, uint256 amount) external {
        if (msg.sender != projectToken) revert OnlyProjectToken();
        if (amount == 0 || from == to) return;
        bool fromEligible = !excluded[from];
        bool toEligible = !excluded[to];
        if (fromEligible) {
            if (eligibleSupply < amount) revert InvalidConfiguration();
            eligibleSupply -= amount;
        }
        if (toEligible) eligibleSupply += amount;
        for (uint256 i; i < _assets.length; ++i) {
            address asset = _assets[i];
            uint256 mps = magnifiedFeePerShare[asset];
            if (fromEligible) _correction[asset][from] += int256(mps * amount);
            if (toEligible) _correction[asset][to] -= int256(mps * amount);
            if (eligibleSupply != 0 && pending[asset] != 0) {
                uint256 deferred = pending[asset];
                pending[asset] = 0;
                _distribute(asset, deferred);
            }
        }
        emit Checkpoint(from, to, amount, eligibleSupply);
    }

    function _distribute(address asset, uint256 amount) private {
        uint256 numerator = amount * MAGNITUDE + magnifiedRemainder[asset];
        magnifiedFeePerShare[asset] += numerator / eligibleSupply;
        magnifiedRemainder[asset] = numerator % eligibleSupply;
    }

    function withdrawableOf(address holder, address asset) public view returns (uint256) {
        if (excluded[holder] || !registeredAsset[asset]) return 0;
        int256 value = int256(magnifiedFeePerShare[asset] * IERC20(projectToken).balanceOf(holder))
            + _correction[asset][holder];
        if (value <= 0) return 0;
        uint256 total = uint256(value) / MAGNITUDE;
        return total > withdrawn[asset][holder] ? total - withdrawn[asset][holder] : 0;
    }

    function correctionOf(address holder, address asset) external view returns (int256) {
        return _correction[asset][holder];
    }

    function claimMany(address[] calldata assets) external returns (uint256 total) {
        if (assets.length == 0 || assets.length > MAX_ASSETS) revert InvalidConfiguration();
        for (uint256 i; i < assets.length; ++i) {
            address asset = assets[i];
            uint256 amount = withdrawableOf(msg.sender, asset);
            if (amount != 0) {
                withdrawn[asset][msg.sender] += amount;
                claimed[asset] += amount;
                IERC20(asset).safeTransfer(msg.sender, amount);
                emit FeeClaimed(msg.sender, asset, amount);
                total += amount;
            }
        }
        if (total == 0) revert NoClaim();
    }
}

contracts/pancake-v1/PancakeV1HolderToke.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {PancakeV1HolderDistributionVault} from "./PancakeV1HolderDistributionVault.sol";

/// @notice Non-upgradeable holder-mode token. The launch factory binds its
/// vault once, then mints the fixed supply; every later balance change is
/// checkpointed before ERC20 state changes.
contract PancakeV1HolderToken is ERC20 {
    uint256 public constant TOTAL_SUPPLY = 1_000_000_000 ether;
    address public immutable launchpad;
    address public immutable factory;
    address public immutable mintRecipient;
    address public immutable poolManager;
    address public immutable positionManager;
    address public immutable locker;
    address public immutable initialBuyRecipient;
    uint256 public immutable launchBlock;
    uint256 public immutable restrictionsEndBlock;
    string private _metadataURI;
    bytes32 public immutable metadataHash;
    PancakeV1HolderDistributionVault public holderVault;
    bool public minted;

    error InvalidConfiguration();
    error VaultAlreadyBound();
    error OnlyLaunchpad();
    error LaunchBlockRestricted();
    error BuyCapExceeded();
    error HoldCapExceeded();

    constructor(
        string memory name_,
        string memory symbol_,
        string memory metadataURI_,
        bytes32 metadataHash_,
        address launchpad_,
        address poolManager_,
        address positionManager_,
        address locker_,
        address initialBuyRecipient_,
        address mintRecipient_,
        uint256 protectionBlocks_
    ) ERC20(name_, symbol_) {
        if (bytes(name_).length == 0 || bytes(symbol_).length == 0 || launchpad_ == address(0)
            || poolManager_ == address(0) || positionManager_ == address(0) || locker_ == address(0)) {
            revert InvalidConfiguration();
        }
        launchpad = launchpad_;
        factory = msg.sender;
        mintRecipient = mintRecipient_;
        poolManager = poolManager_;
        positionManager = positionManager_;
        locker = locker_;
        initialBuyRecipient = initialBuyRecipient_;
        launchBlock = block.number;
        restrictionsEndBlock = block.number + protectionBlocks_;
        _metadataURI = metadataURI_;
        metadataHash = metadataHash_;
    }

    function metadataURI() external view returns (string memory) { return _metadataURI; }
    function tokenURI() external view returns (string memory) { return _metadataURI; }

    function bindVaultAndMint(PancakeV1HolderDistributionVault vault_) external {
        if (msg.sender != launchpad && msg.sender != factory) revert OnlyLaunchpad();
        if (minted || address(vault_) == address(0) || vault_.projectToken() != address(this)) {
            revert VaultAlreadyBound();
        }
        holderVault = vault_;
        minted = true;
        _mint(mintRecipient, TOTAL_SUPPLY);
    }

    function _update(address from, address to, uint256 value) internal override {
        if (address(holderVault) == address(0)) revert InvalidConfiguration();
        holderVault.checkpoint(from, to, value);
        if (restrictionsEndBlock > launchBlock && block.number <= restrictionsEndBlock && from != address(0) && to != address(0)
            && to != poolManager && to != positionManager && to != locker && to != launchpad) {
            if (from == poolManager) {
                if (block.number == launchBlock && to != initialBuyRecipient) revert LaunchBlockRestricted();
                if (value > 55_000_000 ether) revert BuyCapExceeded();
            }
            if (balanceOf(to) + value > 50_000_000 ether) revert HoldCapExceeded();
        }
        super._update(from, to, value);
    }
}

contracts/pancake-v1/PancakeV1InfinityCr.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {PancakeV1InfinityToken} from "./PancakeV1InfinityToken.sol";
import {PancakeV1HolderToken} from "./PancakeV1HolderToken.sol";
import {PancakeV1PermanentPositionLock} from "./PancakeV1PermanentPositionLock.sol";
import {PancakeV1HolderDistributionVault} from "./PancakeV1HolderDistributionVault.sol";
contract PancakeV1InfinityCreationDeployers {
    address public immutable admin;
    address public engine;
    address public immutable positionManager;
    address public immutable tokenLaunchpad;
    address public immutable vault;
    error Unauthorized();
    error AlreadyBound();
    constructor(address admin_,address p,address l,address v){
        require(admin_ != address(0));
        admin=admin_; positionManager=p; tokenLaunchpad=l; vault=v;
    }
    function bindEngine(address engine_) external {
        if (msg.sender != admin || engine != address(0) || engine_ == address(0)) revert Unauthorized();
        engine = engine_;
    }
    function lock(bytes32 salt) external returns(address) {
        if (msg.sender != engine || engine == address(0)) revert Unauthorized();
        return address(new PancakeV1PermanentPositionLock{salt:salt}(positionManager));
    }
    function predictLock(bytes32 salt) external view returns(address) {
        bytes32 h=keccak256(abi.encodePacked(type(PancakeV1PermanentPositionLock).creationCode,abi.encode(positionManager)));
        return address(uint160(uint256(keccak256(abi.encodePacked(bytes1(0xff),address(this),salt,h)))));
    }
    function standard(bytes32 salt,string calldata n,string calldata s,string calldata u,bytes32 h,
        address locker,address creator,address mintTo,uint256 blocks_) external returns(address) {
        if (msg.sender != engine || engine == address(0)) revert Unauthorized();
        return address(new PancakeV1InfinityToken{salt:salt}(
            n,s,u,h,tokenLaunchpad,vault,positionManager,locker,creator,mintTo,blocks_));
    }
    function predictStandard(bytes32 salt,string calldata n,string calldata s,string calldata u,bytes32 h,
        address locker,address creator,address mintTo,uint256 blocks_) external view returns(address) {
        bytes32 initHash = keccak256(abi.encodePacked(type(PancakeV1InfinityToken).creationCode,
            abi.encode(n,s,u,h,tokenLaunchpad,vault,positionManager,locker,creator,mintTo,blocks_)));
        return _create2(salt, initHash);
    }
    function holder(bytes32 salt,string calldata n,string calldata s,string calldata u,bytes32 h,
        address locker,address creator,address mintTo,uint256 blocks_) external returns(address) {
        if (msg.sender != engine || engine == address(0)) revert Unauthorized();
        return address(new PancakeV1HolderToken{salt:salt}(
            n,s,u,h,tokenLaunchpad,vault,positionManager,locker,creator,mintTo,blocks_));
    }
    function predictHolder(bytes32 salt,string calldata n,string calldata s,string calldata u,bytes32 h,
        address locker,address creator,address mintTo,uint256 blocks_) external view returns(address) {
        bytes32 initHash = keccak256(abi.encodePacked(type(PancakeV1HolderToken).creationCode,
            abi.encode(n,s,u,h,tokenLaunchpad,vault,positionManager,locker,creator,mintTo,blocks_)));
        return _create2(salt, initHash);
    }
    function bind(address token, address vault_) external {
        if (msg.sender != engine || engine == address(0)) revert Unauthorized();
        PancakeV1HolderToken(token).bindVaultAndMint(PancakeV1HolderDistributionVault(vault_));
    }
    function _create2(bytes32 salt, bytes32 initHash) private view returns(address) {
        return address(uint160(uint256(keccak256(abi.encodePacked(
            bytes1(0xff), address(this), salt, initHash
        )))));
    }
}

contracts/pancake-v1/PancakeV1InfinityDe.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {PairV5LaunchV2DeveloperBuyRoutePolicy as Routes} from "../v5/PairV5LaunchV2DeveloperBuyRoutePolicy.sol";
import {
    V1PoolKey, V1PoolId, V1Currency, IV1Hooks, IV1PoolManager, IV1Permit2
} from "./PancakeV1Interfaces.sol";
import {
    PancakeV1PoolKey, PancakeV1Currency, IPancakeV1Hooks,
    IPancakeV1CLPoolManager
} from "./PancakeV1InfinityHookTypes.sol";
import {PancakeV1InfinitySwapAdapter} from "./PancakeV1InfinitySwapAdapter.sol";

interface IPancakeV1InfinityWETH is IERC20 { function deposit() external payable; function withdraw(uint256) external; }
interface IPancakeV1InfinitySwapRouter {
    struct ExactInputParams { bytes path; address recipient; uint256 amountIn; uint256 amountOutMinimum; }
    function exactInput(ExactInputParams calldata) external returns (uint256);
}
interface IPancakeV1InfinityUniversalRouter {
    function execute(bytes calldata commands, bytes[] calldata inputs, uint256 deadline) external payable;
}
interface IPancakeV1InfinityPermit2Allowance {
    function allowance(address owner, address token, address spender)
        external view returns (uint160 amount, uint48 expiration, uint48 nonce);
}
interface IPancakeV1InfinityBuySource {
    struct PoolRecord {
        address quoteToken; uint16 weightBps; V1PoolId poolId; uint256 positionId;
        uint256 projectAmount; int24 tickLower; int24 tickUpper; uint256 quotePriceE8; uint8 quoteDecimals;
    }
    function pools(address) external view returns (PoolRecord[] memory);
}
interface IPancakeV1InfinityFeeView {
    function quoteInputFee(address project, uint256 amount) external view returns (uint256);
    function getHooksRegistrationBitmap() external view returns (uint16);
}

/// @notice Typed, hook-bound exact-ETH developer-buy executor for Infinity V1.
/// @dev This is deliberately separate from the historical no-hook executor.
contract PancakeV1InfinityDeveloperBuyExecutor {
    using SafeERC20 for IERC20;

    uint256 private constant BPS = 10_000;
    uint24 private constant POOL_FEE = 10_000;
    int24 private constant TICK_SPACING = 200;
    uint8 public constant BUY_PLAN_VERSION = 1;
    uint8 public constant HOOK_DATA_VERSION = 1;
    bytes32 public constant ROUTE_POLICY_ID = keccak256("pancake-v1-infinity-funding-v1");

    address public immutable launchpad;
    address public engine;
    IV1PoolManager public immutable poolManager;
    IPancakeV1InfinityUniversalRouter public immutable universalRouter;
    IV1Permit2 public immutable permit2;
    address public immutable swapRouter02;
    address public immutable weth;
    address public immutable usdg;
    IPancakeV1InfinityFeeView public immutable hook;
    PancakeV1InfinitySwapAdapter public immutable adapter;
    address public immutable binder;
    bool public engineBound;

    address private constant CANONICAL_WETH = 0x0Bd7D308f8E1639FAb988df18A8011f41EAcAD73;
    address private constant CANONICAL_MANAGER = 0xeE04c68742e6Bf434bE8039580D2e89BBE55bc6f;
    address private constant CANONICAL_ROUTER = 0x57fc55F719DF19B4b90A03F9D78E1177D002E504;
    address private constant CANONICAL_PERMIT2 = 0x31c2F6fcFf4F8759b3Bd5Bf0e1084A055615c768;
    address private constant CANONICAL_SWAP = 0xCaf681a66D020601342297493863E78C959E5cb2;
    address private constant CANONICAL_USDG = 0x5fc5360D0400a0Fd4f2af552ADD042D716F1d168;
    uint256 private _status;

    struct BuyPlan {
        uint8 version;
        address recipient;
        uint256 totalProjectMinimum;
        uint256[] projectMinimums;
        uint256[] quoteMinimums;
        uint256 deadline;
        bytes32 routePolicyId;
    }
    struct HookData { uint8 version; bytes32 poolId; uint256 legIndex; }

    error OnlyEngine();
    error InvalidBuy();
    error UnsupportedRoute(address);
    error Slippage();
    error Residual(address);
    error RefundFailed();

    constructor(
        address launchpad_, address engine_, IV1PoolManager manager_,
        IPancakeV1InfinityUniversalRouter router_, IV1Permit2 permit2_,
        address swapRouter_, address weth_, address usdg_, IPancakeV1InfinityFeeView hook_
    ) {
        if (launchpad_ == address(0) || address(manager_) != CANONICAL_MANAGER
            || address(router_) != CANONICAL_ROUTER || address(permit2_) != CANONICAL_PERMIT2
            || swapRouter_ != CANONICAL_SWAP || weth_ != CANONICAL_WETH || usdg_ != CANONICAL_USDG
            || address(hook_) == address(0) || address(manager_).code.length == 0
            || address(router_).code.length == 0 || address(permit2_).code.length == 0
            || swapRouter_.code.length == 0 || weth_ == usdg_) revert InvalidBuy();
        launchpad = launchpad_; engine = engine_; binder = msg.sender; engineBound = engine_ != address(0);
        poolManager = manager_; universalRouter = router_;
        permit2 = permit2_; swapRouter02 = swapRouter_; weth = weth_; usdg = usdg_; hook = hook_;
        adapter = new PancakeV1InfinitySwapAdapter(
            IPancakeV1CLPoolManager(address(manager_)), IPancakeV1Hooks(address(hook_))
        );
    }

    function bindEngine(address engine_) external {
        if (msg.sender != binder || engineBound || engine_ == address(0)) revert InvalidBuy();
        engine = engine_;
        engineBound = true;
    }

    function routePolicyId() external pure returns (bytes32) { return ROUTE_POLICY_ID; }

    function execute(address project, address payer, uint256 launchDeadline, bytes calldata encodedPlan)
        external payable returns (uint256 received)
    {
        if (!engineBound || msg.sender != engine) revert OnlyEngine();
        BuyPlan memory buy = abi.decode(encodedPlan, (BuyPlan));
        uint256 ethAmount = msg.value;
        if (project == address(0) || payer == address(0) || buy.version != BUY_PLAN_VERSION
            || buy.recipient == address(0) || ethAmount == 0 || buy.totalProjectMinimum == 0
            || buy.routePolicyId != ROUTE_POLICY_ID || buy.projectMinimums.length == 0
            || buy.projectMinimums.length > 5 || buy.projectMinimums.length != buy.quoteMinimums.length
            || buy.deadline < block.timestamp || buy.deadline > type(uint48).max
            || launchDeadline > type(uint48).max || buy.deadline > launchDeadline) revert InvalidBuy();
        if (_status != 0) revert InvalidBuy();
        _status = 1;
        IPancakeV1InfinityBuySource.PoolRecord[] memory pools =
            IPancakeV1InfinityBuySource(launchpad).pools(project);
        if (pools.length == 0 || pools.length > 5 || pools.length != buy.projectMinimums.length) revert InvalidBuy();
        IPancakeV1InfinityWETH wrapped = IPancakeV1InfinityWETH(weth);
        uint256 openingWeth = wrapped.balanceOf(address(this));
        // The launch ETH is converted exactly once, before any leg starts.
        // Keep prefunded WETH outside the refundable accounting baseline.
        wrapped.deposit{value: ethAmount}();
        uint256 fundedWeth = openingWeth + ethAmount;
        if (wrapped.balanceOf(address(this)) != fundedWeth) revert Residual(weth);
        uint256 beforeOut = IERC20(project).balanceOf(buy.recipient);
        uint256 allocated;
        uint256 weightTotal;
        for (uint256 i; i < pools.length; ++i) {
            if (pools[i].weightBps == 0 || buy.projectMinimums[i] == 0 || buy.quoteMinimums[i] == 0) {
                revert InvalidBuy();
            }
            weightTotal += pools[i].weightBps;
            uint256 leg = i + 1 == pools.length ? ethAmount - allocated : ethAmount * pools[i].weightBps / BPS;
            if (leg == 0 || V1PoolId.unwrap(pools[i].poolId) == bytes32(0)) revert InvalidBuy();
            allocated += leg;
            PancakeV1PoolKey memory key = _key(project, pools[i].quoteToken);
            if (keccak256(abi.encode(key)) != V1PoolId.unwrap(pools[i].poolId)) revert InvalidBuy();
            uint256 grossQuote = pools[i].quoteToken == weth
                ? leg
                : _convert(pools[i].quoteToken, leg, buy.quoteMinimums[i]);
            // A negative specified before-swap delta is an additional debit
            // from the specified input.  The amount available from this leg
            // is therefore the gross quote amount, while the CL swap's
            // amountSpecified must be net of the fee.  This is especially
            // important for converted (non-WETH) quotes: converting only the
            // net amount leaves the hook fee unfunded, while specifying the
            // gross amount asks the pool to debit gross + fee.
            _swap(project, pools[i].quoteToken, grossQuote, grossQuote, buy.recipient,
                buy.projectMinimums[i], buy.deadline, pools[i].poolId, i);
        }
        if (weightTotal != BPS || allocated != ethAmount) revert InvalidBuy();
        received = IERC20(project).balanceOf(buy.recipient) - beforeOut;
        if (received < buy.totalProjectMinimum) revert Slippage();
        uint256 closingWeth = wrapped.balanceOf(address(this));
        if (closingWeth < openingWeth) revert Residual(weth);
        if (closingWeth != openingWeth) {
            uint256 refund = closingWeth - openingWeth;
            wrapped.withdraw(refund);
            (bool ok,) = payable(payer).call{value: refund}("");
            if (!ok) revert RefundFailed();
            if (wrapped.balanceOf(address(this)) != openingWeth) revert Residual(weth);
        }
        _status = 0;
    }

    function _convert(address quote, uint256 amount, uint256 minimum) private returns (uint256 result) {
        (uint8 kind, uint24 wethFee, uint24 quoteFee) = Routes.route(quote);
        if (kind == 0 || amount == 0) revert UnsupportedRoute(quote);
        bytes memory path = kind == Routes.DIRECT
            ? abi.encodePacked(weth, wethFee, quote)
            : abi.encodePacked(weth, wethFee, usdg, quoteFee, quote);
        uint256 beforeQuote = IERC20(quote).balanceOf(address(this));
        IERC20(weth).forceApprove(swapRouter02, amount);
        result = IPancakeV1InfinitySwapRouter(swapRouter02).exactInput(
            IPancakeV1InfinitySwapRouter.ExactInputParams(path, address(this), amount, minimum));
        IERC20(weth).forceApprove(swapRouter02, 0);
        uint256 afterQuote = IERC20(quote).balanceOf(address(this));
        if (result == 0 || afterQuote < beforeQuote || afterQuote - beforeQuote != result || result < minimum) {
            revert Slippage();
        }
        if (IERC20(weth).allowance(address(this), swapRouter02) != 0) revert Residual(weth);
    }

    function _swap(address project, address quote, uint256 amount, uint256 gross,
        address recipient, uint256 minimum,
        uint256 deadline, V1PoolId poolId, uint256 legIndex) private {
        if (amount > type(uint128).max || minimum > type(uint128).max || deadline > type(uint48).max) {
            revert InvalidBuy();
        }
        PancakeV1PoolKey memory key = _key(project, quote);
        uint256 beforeOut = IERC20(project).balanceOf(recipient);
        uint256 beforeExecutorOut = IERC20(project).balanceOf(address(this));
        uint256 beforeQuote = IERC20(quote).balanceOf(address(this));
        // quoteInputFee is defined over the specified (net) exact-input
        // amount. Solve net + fee(net) == gross; the fee is floored in the
        // hook. The bounded loop handles both the protocol fee and a possible
        // quote-denominated policy fee without rounding a unit into residue.
        uint256 debit = amount;
        for (uint256 i; i < 256; ++i) {
            uint256 hookFee = hook.quoteInputFee(project, debit);
            if (hookFee >= gross) revert InvalidBuy();
            uint256 next = gross - hookFee;
            if (next == debit) break;
            debit = next;
        }
        uint256 hookFeeFinal = hook.quoteInputFee(project, debit);
        if (hookFeeFinal >= gross || debit + hookFeeFinal != gross) revert InvalidBuy();
        if (debit > type(uint160).max || gross > type(uint160).max) revert InvalidBuy();
        IERC20(quote).forceApprove(address(adapter), gross);
        HookData memory typedHookData = HookData(HOOK_DATA_VERSION, V1PoolId.unwrap(poolId), legIndex);
        bool projectIs0 = project < quote;
        adapter.executeExactInput(
            key, !projectIs0, debit, gross, minimum, address(this), recipient, deadline,
            abi.encode(typedHookData)
        );
        IERC20(quote).forceApprove(address(adapter), 0);
        uint256 executorOut = IERC20(project).balanceOf(address(this)) - beforeExecutorOut;
        if (executorOut != 0) IERC20(project).safeTransfer(recipient, executorOut);
        if (IERC20(project).balanceOf(recipient) - beforeOut < minimum) revert Slippage();
        uint256 afterQuote = IERC20(quote).balanceOf(address(this));
        if (afterQuote > beforeQuote || beforeQuote - afterQuote != gross) revert Residual(quote);
        uint256 principalConsumed = beforeQuote - afterQuote;
        if (principalConsumed != gross) revert Residual(quote);
        if (IERC20(quote).allowance(address(this), address(adapter)) != 0) revert Residual(quote);
    }

    function _key(address project, address quote) private view returns (PancakeV1PoolKey memory) {
        bool projectIs0 = project < quote;
        uint16 bitmap = hook.getHooksRegistrationBitmap();
        return PancakeV1PoolKey(
            PancakeV1Currency.wrap(projectIs0 ? project : quote),
            PancakeV1Currency.wrap(projectIs0 ? quote : project),
            IPancakeV1Hooks(address(hook)), IPancakeV1CLPoolManager(address(poolManager)), POOL_FEE,
            bytes32(uint256(bitmap) | (uint256(uint24(uint24(TICK_SPACING))) << 16))
        );
    }

    receive() external payable { if (msg.sender != weth) revert InvalidBuy(); }
}

contracts/pancake-v1/PancakeV1InfinityDi.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {
    V1PoolId
} from "./PancakeV1Interfaces.sol";
import {
    PancakeV1PoolKey, PancakeV1Currency, IPancakeV1Hooks,
    IPancakeV1CLPoolManager
} from "./PancakeV1InfinityHookTypes.sol";
interface IPancakeV1DirectBuyPermit2 {
    function approve(address token, address spender, uint160 amount, uint48 expiration) external;
}
interface IPancakeV1DirectBuyRouter {
    struct PoolKey { address currency0; address currency1; address hooks; address poolManager; uint24 fee; bytes32 parameters; }
    struct SwapParams { PoolKey poolKey; bool zeroForOne; uint128 amountIn; uint128 amountOutMinimum; bytes hookData; }
    function execute(bytes calldata commands, bytes[] calldata inputs, uint256 deadline) external payable;
}

interface IPancakeV1DirectBuyAdapter {
    function executeExactInput(
        PancakeV1PoolKey calldata key,
        bool zeroForOne,
        uint256 amountIn,
        uint256 inputMaximum,
        uint256 amountOutMinimum,
        address payer,
        address recipient,
        uint256 deadline,
        bytes calldata hookData
    ) external returns (uint256 amountOut);
}

interface IPancakeV1DirectBuySource {
    struct PoolRecord {
        address quoteToken; uint16 weightBps; V1PoolId poolId; uint256 positionId;
        uint256 projectAmount; int24 tickLower; int24 tickUpper; uint256 quotePriceE8; uint8 quoteDecimals;
    }
    function pools(address) external view returns (PoolRecord[] memory);
}

interface IPancakeV1DirectBuyHook {
    function quoteInputFee(address project, uint256 amount) external view returns (uint256);
    function getHooksRegistrationBitmap() external view returns (uint16);
}
interface IPancakeV1DirectBuyLaunchpad {
    function launchInfinityFor(address creator, bytes calldata encoded)
        external payable returns (address);
    function poolManager() external view returns (address);
}

/// @notice Versioned, all-direct quote-token developer buys for Infinity V1.
/// @dev The existing exact-ETH executor is intentionally not changed. This
/// executor is only callable by the active launchpad proxy and only consumes
/// quote tokens declared by the creator in a typed plan.
contract PancakeV1InfinityDirectQuoteDeveloperBuyExecutor {
    using SafeERC20 for IERC20;

    uint24 private constant POOL_FEE = 10_000;
    int24 private constant TICK_SPACING = 200;
    uint8 public constant BUY_PLAN_VERSION = 1;
    uint8 public constant HOOK_DATA_VERSION = 1;
    bytes32 public constant ROUTE_POLICY_ID =
        keccak256("pancake-v1-infinity-direct-quote-v1");

    address public immutable launchpad;
    IPancakeV1CLPoolManager public immutable poolManager;
    IPancakeV1DirectBuyHook public immutable hook;
    IPancakeV1DirectBuyAdapter public immutable adapter;
    IPancakeV1DirectBuyPermit2 public immutable permit2;
    uint256 private _status;

    struct BuyPlan {
        uint8 version;
        address recipient;
        uint256 totalProjectMinimum;
        uint256[] projectMinimums;
        uint256[] quoteAmounts;
        uint256 deadline;
        bytes32 routePolicyId;
    }
    struct HookData { uint8 version; bytes32 poolId; uint256 legIndex; }
    struct Leg {
        address project;
        address payer;
        address quote;
        uint256 amount;
        address recipient;
        uint256 minimum;
        uint256 deadline;
        V1PoolId poolId;
        uint256 legIndex;
    }

    error OnlyLaunchpad();
    error InvalidBuy();
    error PoolBindingMismatch(bytes32 storedPoolId, bytes32 computedPoolId);
    error Slippage();
    error Residual(address token);
    error RefundFailed();

    constructor(
        address launchpad_,
        IPancakeV1CLPoolManager manager_,
        IPancakeV1DirectBuyHook hook_,
        IPancakeV1DirectBuyAdapter adapter_,
        IPancakeV1DirectBuyPermit2 permit2_
    ) {
        if (launchpad_ == address(0) || address(manager_) == address(0)
            || address(manager_).code.length == 0 || address(hook_).code.length == 0
            || address(manager_.vault()).code.length == 0 || address(adapter_).code.length == 0
            || address(permit2_).code.length == 0) revert InvalidBuy();
        launchpad = launchpad_;
        poolManager = manager_;
        hook = hook_;
        adapter = adapter_;
        permit2 = permit2_;
    }

    function routePolicyId() external pure returns (bytes32) { return ROUTE_POLICY_ID; }

    function execute(
        address project,
        address payer,
        bytes calldata encodedPlan
    ) external payable {
        if ((msg.sender != launchpad && msg.sender != address(this))
            || project == address(0) || payer == address(0)
            || msg.value != 0) revert OnlyLaunchpad();
        BuyPlan memory buy = abi.decode(encodedPlan, (BuyPlan));
        if (buy.version != BUY_PLAN_VERSION || buy.recipient == address(0)
            || buy.totalProjectMinimum == 0 || buy.routePolicyId != ROUTE_POLICY_ID
            || buy.projectMinimums.length == 0 || buy.projectMinimums.length > 5
            || buy.projectMinimums.length != buy.quoteAmounts.length
            || buy.deadline < block.timestamp || buy.deadline > type(uint48).max) {
            revert InvalidBuy();
        }
        if (_status != 0) revert InvalidBuy();
        _status = 1;

        IPancakeV1DirectBuySource.PoolRecord[] memory pools =
            IPancakeV1DirectBuySource(launchpad).pools(project);
        if (pools.length == 0 || pools.length > 5
            || pools.length != buy.projectMinimums.length) revert InvalidBuy();

        uint256 received = _executeLegs(project, payer, buy, pools);
        if (received < buy.totalProjectMinimum) revert Slippage();
        if (IERC20(project).balanceOf(address(this)) != 0) revert Residual(project);
        _status = 0;
    }

    /// @notice Atomic direct-quote launch followed by the typed buy plan.
    /// @dev The creator approves this coordinator, never the launchpad proxy.
    function launchAndBuy(bytes calldata launchData, bytes calldata encodedPlan)
        external payable virtual returns (address project) {
        project = IPancakeV1DirectBuyLaunchpad(launchpad).launchInfinityFor{value: msg.value}(
            msg.sender, launchData
        );
        this.execute(project, msg.sender, encodedPlan);
    }

    function _executeLegs(
        address project,
        address payer,
        BuyPlan memory buy,
        IPancakeV1DirectBuySource.PoolRecord[] memory pools
    ) private returns (uint256 received) {
        uint256 beforeOut = IERC20(project).balanceOf(buy.recipient);
        uint256 weightTotal;
        for (uint256 i; i < pools.length; ++i) {
            weightTotal += pools[i].weightBps;
            _executeLeg(project, payer, buy, pools[i], i);
        }
        if (weightTotal != 10_000) revert InvalidBuy();
        received = IERC20(project).balanceOf(buy.recipient) - beforeOut;
    }

    function _executeLeg(
        address project,
        address payer,
        BuyPlan memory buy,
        IPancakeV1DirectBuySource.PoolRecord memory pool,
        uint256 legIndex
    ) private {
        uint256 amount = buy.quoteAmounts[legIndex];
        if (pool.weightBps == 0 || amount == 0 || buy.projectMinimums[legIndex] == 0
            || V1PoolId.unwrap(pool.poolId) == bytes32(0)) revert InvalidBuy();
        PancakeV1PoolKey memory key = _key(project, pool.quoteToken);
        bytes32 computedPoolId = keccak256(abi.encode(key));
        if (computedPoolId != V1PoolId.unwrap(pool.poolId)) {
            revert PoolBindingMismatch(V1PoolId.unwrap(pool.poolId), computedPoolId);
        }
        _buyLeg(Leg(
            project, payer, pool.quoteToken, amount, buy.recipient,
            buy.projectMinimums[legIndex], buy.deadline, pool.poolId, legIndex
        ));
    }

    function _buyLeg(Leg memory leg) private {
        address project = leg.project;
        address payer = leg.payer;
        address quote = leg.quote;
        uint256 amount = leg.amount;
        address recipient = leg.recipient;
        uint256 minimum = leg.minimum;
        uint256 deadline = leg.deadline;
        V1PoolId poolId = leg.poolId;
        uint256 legIndex = leg.legIndex;
        if (amount > type(uint128).max || minimum > type(uint128).max
            || deadline > type(uint48).max
            || IERC20(quote).balanceOf(address(this)) != 0) revert InvalidBuy();
        uint256 payerBefore = IERC20(quote).balanceOf(payer);
        IERC20(quote).safeTransferFrom(payer, address(this), amount);
        if (IERC20(quote).balanceOf(address(this)) != amount
            || payerBefore < IERC20(quote).balanceOf(payer)
            || payerBefore - IERC20(quote).balanceOf(payer) != amount) {
            revert Residual(quote);
        }
        uint256 debit = amount;
        for (uint256 i; i < 256; ++i) {
            uint256 fee = hook.quoteInputFee(project, debit);
            if (fee >= amount) revert InvalidBuy();
            uint256 next = amount - fee;
            if (next == debit) break;
            debit = next;
        }
        uint256 finalFee = hook.quoteInputFee(project, debit);
        if (finalFee >= amount || debit + finalFee != amount) revert InvalidBuy();
        IERC20(quote).forceApprove(address(adapter), amount);
        PancakeV1PoolKey memory key = _key(project, quote);
        uint256 beforeOut = IERC20(project).balanceOf(recipient);
        uint256 beforeExecutorOut = IERC20(project).balanceOf(address(this));
        IPancakeV1DirectBuyAdapter(adapter).executeExactInput(
            key, project >= quote, debit, amount, minimum, address(this), recipient, deadline,
            abi.encode(HookData(HOOK_DATA_VERSION, V1PoolId.unwrap(poolId), legIndex)
        ));
        uint256 executorOut = IERC20(project).balanceOf(address(this)) - beforeExecutorOut;
        if (executorOut != 0) IERC20(project).safeTransfer(recipient, executorOut);
        if (IERC20(project).balanceOf(address(this)) < beforeExecutorOut
            || IERC20(project).balanceOf(address(this)) - beforeExecutorOut != 0
            || IERC20(project).balanceOf(recipient) - beforeOut < minimum) revert Slippage();
        uint256 afterQuote = IERC20(quote).balanceOf(address(this));
        if (afterQuote != 0 || IERC20(quote).allowance(address(this), address(adapter)) != 0) {
            revert Residual(quote);
        }
    }

    function _key(address project, address quote) private view returns (PancakeV1PoolKey memory) {
        bool projectIs0 = project < quote;
        return PancakeV1PoolKey(
            PancakeV1Currency.wrap(projectIs0 ? project : quote),
            PancakeV1Currency.wrap(projectIs0 ? quote : project),
            IPancakeV1Hooks(address(hook)), poolManager, POOL_FEE,
            bytes32(uint256(hook.getHooksRegistrationBitmap())
                | (uint256(uint24(uint24(TICK_SPACING))) << 16))
        );
    }

    receive() external payable { revert InvalidBuy(); }
}

