// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {
    PancakeV1Currency,
    PancakeV1BeforeSwapDelta,
    PancakeV1BalanceDelta,
    PancakeV1PoolKey,
    IPancakeV1Hooks,
    IPancakeV1CLPoolManager,
    IPancakeV1Vault,
    IPancakeV1FeeReceiver,
    PancakeV1BalanceDeltaLib,
    PancakeV1BeforeSwapDeltaLib
} from "./PancakeV1InfinityHookTypes.sol";

interface IPancakeV1FeeSettler {
    function settleHookFee(address asset, address destination, uint256 amount) external;
}

interface IPancakeV1InfinityReleaseEngine {
    function hook() external view returns (address);
    function factory() external view returns (address);
}

interface IPancakeV1InfinityReleaseFactory {
    function hook() external view returns (address);
    function engine() external view returns (address);
}

/// @notice Infinity CL hook core for the new PANCAKE_V1 release only.
/// @dev This hook is deliberately immutable. Infinity validates the callback
/// bitmap from the PoolKey parameters and the hook address is part of PoolId;
/// proxying it would make address/permission mistakes a pool-identity risk.
contract PancakeV1InfinityHook is Ownable, IPancakeV1Hooks {
    using PancakeV1BalanceDeltaLib for PancakeV1BalanceDelta;

    uint16 public constant BPS = 10_000;
    uint16 public constant PROTOCOL_FEE_BPS = 30;
    uint16 public constant MAX_MODE_FEE_BPS = 1_000;
    uint16 public constant HOOK_BITMAP = (1 << 6) | (1 << 7) | (1 << 10) | (1 << 11);
    address public constant BURN = 0x000000000000000000000000000000000000dEaD;

    enum FeeMode { NONE, CREATOR_QUOTE, BURN_PROJECT, FEE_SHARING_QUOTE, HOLDER_QUOTE }
    struct PoolConfig {
        address project;
        address quote;
        uint160 graduationSqrtPriceX96;
        bool graduateWhenAbove;
        bool registered;
    }
    struct Policy {
        FeeMode mode;
        uint16 feeBps;
        address destination;
        uint64 effectiveAt;
    }
    struct PendingFee {
        address project;
        address quote;
        address modeAsset;
        address modeDestination;
        uint256 protocolFee;
        uint256 modeFee;
    }
    struct TokenState {
        uint64 currentEpoch;
        bool graduated;
        bool holderMode;
    }

    IPancakeV1CLPoolManager public immutable poolManager;
    address public registrar;
    address public immutable protocolVault;
    address public attestor;
    bool public frozen;
    mapping(bytes32 => PoolConfig) public pools;
    mapping(address => TokenState) public tokenStates;
    mapping(address => mapping(uint64 => Policy)) public policies;
    mapping(address => PendingFee) private _pendingFees;

    error OnlyPoolManager();
    error OnlyRegistrar();
    error UnknownPool();
    error InvalidPool();
    error InvalidPolicy();
    error HolderTransition();
    error AlreadyRegistered();
    error GraduationReadFailed();
    error UnattestedVault();

    event PoolRegistered(bytes32 indexed poolId, address indexed project, address indexed quote,
        uint160 graduationSqrtPriceX96, bool graduateWhenAbove);
    event PolicyScheduled(address indexed project, uint64 indexed epoch, FeeMode mode,
        uint16 feeBps, address destination, uint64 effectiveAt);
    event TokenGraduated(address indexed project, bytes32 indexed poolId, uint160 sqrtPriceX96);
    event ProtocolFeeAccrued(address indexed quote, address indexed destination, uint256 amount);
    event ModeFeeAccrued(address indexed project, address indexed asset, address indexed destination, uint256 amount);

    constructor(IPancakeV1CLPoolManager manager_, address /*registrar_*/, address owner_, address protocolVault_)
        Ownable(owner_) {
        if (address(manager_) == address(0) || protocolVault_ == address(0)
            || protocolVault_.code.length == 0) {
            revert InvalidPool();
        }
        address vault_ = manager_.vault();
        if (vault_ == address(0) || vault_.code.length == 0) revert InvalidPool();
        _validateReceiver(protocolVault_);
        poolManager = manager_;
        // Retain the old constructor shape for artifact compatibility, but
        // never trust a constructor-supplied registrar.  The protected admin
        // binds it exactly once after the reciprocal release graph exists.
        protocolVault = protocolVault_;
    }

    function getHooksRegistrationBitmap() external pure returns (uint16) {
        return HOOK_BITMAP;
    }

    function finalizeRelease(address engine_, address factory_) external onlyOwner {
        if (frozen || engine_.code.length == 0 || factory_.code.length == 0) revert InvalidPolicy();
        if (IPancakeV1InfinityReleaseEngine(engine_).hook() != address(this)
            || IPancakeV1InfinityReleaseEngine(engine_).factory() != factory_
            || IPancakeV1InfinityReleaseFactory(factory_).hook() != address(this)
            || IPancakeV1InfinityReleaseFactory(factory_).engine() != engine_) {
            revert InvalidPolicy();
        }
        registrar = engine_;
        attestor = factory_;
        frozen = true;
    }

    /// @notice Exact fee debited in quote units when an exact-input quote swap
    /// is executed. Keeping the two floor operations here lets the developer
    /// buy prove the complete quote debit without accepting an arbitrary
    /// slippage allowance for hook fees.
    function quoteInputFee(address project, uint256 amount) external view returns (uint256) {
        Policy memory policy = activePolicy(project);
        uint256 fee = amount * PROTOCOL_FEE_BPS / BPS;
        if (policy.mode != FeeMode.BURN_PROJECT && policy.mode != FeeMode.NONE) {
            fee += amount * policy.feeBps / BPS;
        }
        return fee;
    }

    function poolId(PancakeV1PoolKey calldata key) public pure returns (bytes32) {
        return keccak256(abi.encode(key));
    }

    function registerPool(
        PancakeV1PoolKey calldata key,
        address project,
        address quote,
        uint160 graduationSqrtPriceX96,
        bool graduateWhenAbove
    ) external {
        if (!frozen || msg.sender != registrar) revert OnlyRegistrar();
        if (address(key.hooks) != address(this) || address(key.poolManager) != address(poolManager)
            || project == address(0) || quote == address(0) || project == quote
            || graduationSqrtPriceX96 == 0) revert InvalidPool();
        address c0 = PancakeV1Currency.unwrap(key.currency0);
        address c1 = PancakeV1Currency.unwrap(key.currency1);
        if (!((c0 == project && c1 == quote) || (c0 == quote && c1 == project))) revert InvalidPool();
        bytes32 id = poolId(key);
        if (pools[id].registered) revert AlreadyRegistered();
        pools[id] = PoolConfig(project, quote, graduationSqrtPriceX96, graduateWhenAbove, true);
        emit PoolRegistered(id, project, quote, graduationSqrtPriceX96, graduateWhenAbove);
    }

    /// @notice Append a policy epoch. effectiveAt is intentionally admin
    /// selected and may be block.timestamp (there is no forced timelock).
    function schedulePolicy(address project, FeeMode mode, uint16 feeBps, address destination,
        uint64 effectiveAt) external returns (uint64 epoch) {
        if (msg.sender != owner() && (!frozen || msg.sender != registrar)) revert OnlyRegistrar();
        // Zero is the explicit immediate-activation sentinel. This avoids a
        // race between reading the latest block and mining the admin tx while
        // retaining strict rejection of stale non-zero timestamps.
        if (effectiveAt == 0) effectiveAt = uint64(block.timestamp);
        if (project == address(0) || effectiveAt < block.timestamp) revert InvalidPolicy();
        if (mode == FeeMode.NONE) {
            if (feeBps != 0 || destination != address(0)) revert InvalidPolicy();
        } else {
            if (feeBps == 0 || feeBps > MAX_MODE_FEE_BPS || feeBps % 100 != 0) revert InvalidPolicy();
            if (mode == FeeMode.BURN_PROJECT && destination != BURN) revert InvalidPolicy();
            if (mode != FeeMode.BURN_PROJECT && destination == address(0)) revert InvalidPolicy();
            if (!frozen || mode != FeeMode.BURN_PROJECT) {
                (bool ok, bytes memory data) = attestor.staticcall(abi.encodeWithSignature(
                    "verifyVault(address,uint8,address)", project, uint8(mode), destination));
                if (!ok || data.length < 32 || !abi.decode(data, (bool))) revert UnattestedVault();
            }
            if (mode != FeeMode.BURN_PROJECT) _validateReceiver(destination);
        }
        TokenState storage state = tokenStates[project];
        bool holder = mode == FeeMode.HOLDER_QUOTE;
        if (state.currentEpoch != 0 && holder != state.holderMode) revert HolderTransition();
        epoch = state.currentEpoch + 1;
        policies[project][epoch] = Policy(mode, feeBps, destination, effectiveAt);
        state.currentEpoch = epoch;
        state.holderMode = holder;
        emit PolicyScheduled(project, epoch, mode, feeBps, destination, effectiveAt);
    }

    function activePolicy(address project) public view returns (Policy memory result) {
        TokenState memory state = tokenStates[project];
        if (state.currentEpoch == 0) return result;
        result = policies[project][state.currentEpoch];
        uint64 epoch = state.currentEpoch;
        while (result.effectiveAt > block.timestamp && epoch > 1) {
            result = policies[project][--epoch];
        }
        if (result.effectiveAt > block.timestamp) result = Policy(FeeMode.NONE, 0, address(0), 0);
    }

    function beforeSwap(address sender, PancakeV1PoolKey calldata key,
        IPancakeV1CLPoolManager.SwapParams calldata params, bytes calldata)
        external view returns (bytes4, PancakeV1BeforeSwapDelta, uint24) {
        if (msg.sender != address(poolManager)) revert OnlyPoolManager();
        _authorizeAdapter(sender);
        _pool(key);
        key;
        params;
        // Fees are settled from the authenticated adapter's gross input/output
        // credits. Infinity's specified custom delta creates a matching hook
        // debt, so it cannot safely collect an additive fee.
        return (this.beforeSwap.selector, PancakeV1BeforeSwapDeltaLib.toDelta(0, 0), 0);
    }

    function afterSwap(address sender, PancakeV1PoolKey calldata key,
        IPancakeV1CLPoolManager.SwapParams calldata params, PancakeV1BalanceDelta delta, bytes calldata)
        external returns (bytes4, int128) {
        if (msg.sender != address(poolManager)) revert OnlyPoolManager();
        _authorizeAdapter(sender);
        PoolConfig memory p = _pool(key);
        bytes32 id = poolId(key);
        _syncGraduation(id, p);
        (uint256 protocolSpecified, uint256 modeSpecified) = _feeQuote(key, p, params);
        (uint256 protocolFee, uint256 modeFee, uint256 unspecifiedFee) =
            _feeQuoteAfter(key, p, params, delta);
        if (protocolSpecified != 0 || modeSpecified != 0) {
            _settleFees(sender, p, protocolSpecified, modeSpecified);
        }
        if (unspecifiedFee != 0) {
            PendingFee storage pending = _pendingFees[sender];
            if (pending.protocolFee != 0 || pending.modeFee != 0) revert InvalidPolicy();
            Policy memory policy = activePolicy(p.project);
            pending.project = p.project;
            pending.quote = p.quote;
            pending.modeAsset = policy.mode == FeeMode.BURN_PROJECT ? p.project : p.quote;
            pending.modeDestination = policy.destination;
            pending.protocolFee = protocolFee;
            pending.modeFee = modeFee;
        }
        // Unspecified output credit is posted to the adapter only after this
        // callback returns. settleUnspecifiedFee() consumes the pending fee
        // from that adapter credit without creating any hook delta.
        return (this.afterSwap.selector, 0);
    }

    function settleUnspecifiedFee() external {
        _authorizeAdapter(msg.sender);
        if (msg.sender.code.length == 0) revert InvalidPolicy();
        PendingFee memory pending = _pendingFees[msg.sender];
        if (pending.protocolFee == 0 && pending.modeFee == 0) return;
        delete _pendingFees[msg.sender];
        if (pending.protocolFee != 0) {
            IPancakeV1FeeSettler(msg.sender).settleHookFee(
                pending.quote, protocolVault, pending.protocolFee
            );
            IPancakeV1FeeReceiver(protocolVault).recordFee(
                pending.quote, pending.protocolFee
            );
            emit ProtocolFeeAccrued(pending.quote, protocolVault, pending.protocolFee);
        }
        if (pending.modeFee != 0) {
            IPancakeV1FeeSettler(msg.sender).settleHookFee(
                pending.modeAsset, pending.modeDestination, pending.modeFee
            );
            if (pending.modeDestination != BURN) {
                IPancakeV1FeeReceiver(pending.modeDestination).recordFee(
                    pending.modeAsset, pending.modeFee
                );
            }
            emit ModeFeeAccrued(
                pending.project, pending.modeAsset, pending.modeDestination, pending.modeFee
            );
        }
    }

    function _pool(PancakeV1PoolKey calldata key) private view returns (PoolConfig memory p) {
        p = pools[poolId(key)];
        if (!p.registered) revert UnknownPool();
    }

    /// @dev Historical releases retain their behavior. New chain candidates
    /// override this boundary to enforce cooperative settlement adapters.
    function _authorizeAdapter(address) internal view virtual {}

    function _syncGraduation(bytes32 id, PoolConfig memory p) private {
        TokenState storage state = tokenStates[p.project];
        if (state.graduated) return;
        (bool ok, bytes memory data) = address(poolManager).staticcall(
            abi.encodeCall(IPancakeV1CLPoolManager.getSlot0, (id)));
        if (!ok || data.length < 32) revert GraduationReadFailed();
        (uint160 current,,,) = abi.decode(data, (uint160, int24, uint24, uint24));
        bool reached = p.graduateWhenAbove
            ? current >= p.graduationSqrtPriceX96
            : current <= p.graduationSqrtPriceX96;
        if (reached) {
            state.graduated = true;
            emit TokenGraduated(p.project, id, current);
        }
    }

    function _feeQuote(PancakeV1PoolKey calldata key, PoolConfig memory p,
        IPancakeV1CLPoolManager.SwapParams calldata params)
        private view returns (uint256 protocol, uint256 mode) {
        bool exactInput = params.amountSpecified < 0;
        bool quoteInput = params.zeroForOne
            ? PancakeV1Currency.unwrap(key.currency0) == p.quote
            : PancakeV1Currency.unwrap(key.currency1) == p.quote;
        bool specifiedIsQuote = quoteInput == exactInput;
        uint256 amount = uint256(exactInput ? -params.amountSpecified : params.amountSpecified);
        Policy memory policy = activePolicy(p.project);
        protocol = specifiedIsQuote ? amount * PROTOCOL_FEE_BPS / BPS : 0;
        bool modeIsQuote = policy.mode != FeeMode.BURN_PROJECT;
        mode = _modeFee(policy, modeIsQuote == specifiedIsQuote, amount);
    }

    function _feeQuoteAfter(PancakeV1PoolKey calldata key, PoolConfig memory p,
        IPancakeV1CLPoolManager.SwapParams calldata params, PancakeV1BalanceDelta delta)
        private view returns (uint256 protocol, uint256 mode, uint256 unspecifiedFee) {
        bool exactInput = params.amountSpecified < 0;
        bool quoteInput = params.zeroForOne
            ? PancakeV1Currency.unwrap(key.currency0) == p.quote
            : PancakeV1Currency.unwrap(key.currency1) == p.quote;
        bool specifiedIsQuote = quoteInput == exactInput;
        int128 amount0 = delta.amount0();
        int128 amount1 = delta.amount1();
        bool quote0 = p.quote == PancakeV1Currency.unwrap(key.currency0);
        int128 q = quote0 ? amount0 : amount1;
        int128 t = quote0 ? amount1 : amount0;
        uint256 quoteAmount = uint256(q < 0 ? -int256(q) : int256(q));
        uint256 projectAmount = uint256(t < 0 ? -int256(t) : int256(t));
        Policy memory policy = activePolicy(p.project);
        protocol = specifiedIsQuote ? 0
            : quoteAmount * PROTOCOL_FEE_BPS / BPS;
        bool modeIsQuote = policy.mode != FeeMode.BURN_PROJECT;
        if (policy.mode == FeeMode.NONE) {
            mode = 0;
        } else if (modeIsQuote) {
            mode = specifiedIsQuote ? 0 : quoteAmount * policy.feeBps / BPS;
        } else {
            mode = specifiedIsQuote ? projectAmount * policy.feeBps / BPS : 0;
        }
        unspecifiedFee = protocol + mode;
    }

    function _modeFee(Policy memory policy, bool feeAssetIsSpecified, uint256 amount)
        private pure returns (uint256) {
        if (policy.mode == FeeMode.NONE) return 0;
        if (!feeAssetIsSpecified) return 0;
        return amount * policy.feeBps / BPS;
    }

    function _settleFees(
        address sender,
        PoolConfig memory p,
        uint256 protocolFee,
        uint256 modeFee
    ) private {
        if (sender.code.length == 0) revert InvalidPolicy();
        if (protocolFee != 0) {
            IPancakeV1FeeSettler(sender).settleHookFee(
                p.quote, protocolVault, protocolFee
            );
            IPancakeV1FeeReceiver(protocolVault).recordFee(p.quote, protocolFee);
            emit ProtocolFeeAccrued(p.quote, protocolVault, protocolFee);
        }
        if (modeFee != 0) {
            Policy memory policy = activePolicy(p.project);
            address asset = policy.mode == FeeMode.BURN_PROJECT ? p.project : p.quote;
            IPancakeV1FeeSettler(sender).settleHookFee(
                asset, policy.destination, modeFee
            );
            if (policy.destination != BURN) {
                IPancakeV1FeeReceiver(policy.destination).recordFee(asset, modeFee);
            }
            emit ModeFeeAccrued(p.project, asset, policy.destination, modeFee);
        }
    }

    function _toInt128(uint256 value) private pure returns (int128) {
        require(value <= uint256(uint128(type(int128).max)), "FEE_OVERFLOW");
        return int128(uint128(value));
    }

    function _validateReceiver(address receiver) private view {
        if (receiver.code.length == 0) revert InvalidPolicy();
        // Keep the compatibility check typed, rather than treating arbitrary
        // destinations as fee sinks. The call itself is made after take().
        IPancakeV1FeeReceiver(receiver);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @notice Narrow ABI-compatible Pancake Infinity CL types.  These are
/// intentionally vendored because the application does not pin the upstream
/// Infinity package as a Solidity dependency.
type PancakeV1Currency is address;
type PancakeV1BeforeSwapDelta is int256;
type PancakeV1BalanceDelta is int256;

interface IPancakeV1Hooks {
    function getHooksRegistrationBitmap() external view returns (uint16);
}

interface IPancakeV1CLPoolManager {
    struct SwapParams {
        bool zeroForOne;
        int256 amountSpecified;
        uint160 sqrtPriceLimitX96;
    }

    function vault() external view returns (address);
    function getSlot0(bytes32 poolId)
        external view returns (uint160 sqrtPriceX96, int24 tick, uint24 protocolFee, uint24 lpFee);
    function swap(
        PancakeV1PoolKey calldata key,
        SwapParams calldata params,
        bytes calldata hookData
    ) external returns (PancakeV1BalanceDelta delta);
}

interface IPancakeV1Vault {
    function manager() external view returns (address);
    function lock(bytes calldata data) external returns (bytes memory);
    function currencyDelta(address settler, PancakeV1Currency currency) external view returns (int256);
    function getUnsettledDeltasCount() external view returns (uint256);
    function sync(PancakeV1Currency currency) external;
    function settleFor(address recipient) external payable returns (uint256);
    function take(PancakeV1Currency currency, address to, uint256 amount) external;
}

interface IPancakeV1LockCallback {
    function lockAcquired(bytes calldata data) external returns (bytes memory);
}

interface IPancakeV1FeeReceiver {
    function recordFee(address asset, uint256 amount) external;
}

struct PancakeV1PoolKey {
    PancakeV1Currency currency0;
    PancakeV1Currency currency1;
    IPancakeV1Hooks hooks;
    IPancakeV1CLPoolManager poolManager;
    uint24 fee;
    bytes32 parameters;
}

library PancakeV1BalanceDeltaLib {
    function amount0(PancakeV1BalanceDelta delta) internal pure returns (int128 value) {
        assembly ("memory-safe") { value := sar(128, delta) }
    }

    function amount1(PancakeV1BalanceDelta delta) internal pure returns (int128 value) {
        assembly ("memory-safe") { value := signextend(15, delta) }
    }
}

library PancakeV1BeforeSwapDeltaLib {
    function toDelta(int128 specified, int128 unspecified)
        internal pure returns (PancakeV1BeforeSwapDelta value) {
        assembly ("memory-safe") {
            value := or(shl(128, specified), and(sub(shl(128, 1), 1), unspecified))
        }
    }
}

contracts/pancake-v1/PancakeV1InfinityLa.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {PancakeV1InfinityLaunchFactory} from "./PancakeV1InfinityLaunchFactory.sol";
import {PancakeV1InfinityPoolBootstrapper} from "./PancakeV1InfinityPoolBootstrapper.sol";
import {PancakeV1FeeSharingVault} from "./PancakeV1FeeSharingVault.sol";
import {IPancakeV1Hooks, IPancakeV1CLPoolManager, PancakeV1PoolKey, PancakeV1Currency} from "./PancakeV1InfinityHookTypes.sol";

interface IPancakeV1InfinityLaunchpad {
    function launchFee() external view returns (uint256);
    function launchFeeRecipient() external view returns (address);
    function poolManager() external view returns (address);
    function positionManager() external view returns (address);
    function permit2() external view returns (address);
    function infinityApprove(address token, uint256 amount, uint256 deadline) external;
    function recordInfinityPool(address,address,bytes32,uint16) external;
    function modeVault(address project, uint8 mode, bytes calldata modeData, uint16 feeBps)
        external returns (address);
}
interface IPancakeV1Permit2 {
    function approve(address token, address spender, uint160 amount, uint48 expiration) external;
}

interface IPancakeV1InfinityHookEngine {
    enum FeeMode { NONE, CREATOR_QUOTE, BURN_PROJECT, FEE_SHARING_QUOTE, HOLDER_QUOTE }
    function getHooksRegistrationBitmap() external view returns (uint16);
    function schedulePolicy(address, FeeMode, uint16, address, uint64) external returns (uint64);
    function registerPool(PancakeV1PoolKey calldata,address,address,uint160,bool) external;
    function poolManager() external view returns(address);
    function registrar() external view returns(address);
    function owner() external view returns(address);
    function frozen() external view returns(bool);
}
interface IPancakeV1InfinityDeveloperBuy {
    function launchpad() external view returns(address);
    function engine() external view returns(address);
    function poolManager() external view returns(address);
    function hook() external view returns(address);
    function execute(address project, address payer, uint256 launchDeadline, bytes calldata encodedPlan)
        external payable returns (uint256);
}

/// @notice Immutable ordinary-call orchestrator. It never owns launch tokens:
/// the launchpad proxy remains the ERC20 owner and approves Infinity Permit2
/// through its engine-only gateway for each mint.
contract PancakeV1InfinityLaunchEngine {
    using SafeERC20 for IERC20;
    address public immutable launchpad;
    PancakeV1InfinityLaunchFactory public immutable factory;
    PancakeV1InfinityPoolBootstrapper public immutable bootstrapper;
    IPancakeV1InfinityHookEngine public immutable hook;
    IPancakeV1InfinityDeveloperBuy public immutable developerBuyExecutor;

    struct Allocation { address quoteToken; uint16 weightBps; }
    struct Params {
        bytes identityData;
        Allocation[] allocations;
        bytes[] openingData;
        uint256 deadline;
        bytes32 userSalt;
        bool sniperProtection;
        uint256 protectionBlocks;
        IPancakeV1InfinityHookEngine.FeeMode mode;
        uint16 feeBps;
        bytes modeData;
        uint64 policyEffectiveAt;
        address[] holderExcluded;
    }
    struct Opening {
        uint8 decimals; uint160 opening; int24 lower; int24 upper; uint256 observed;
        bytes32 evidence; uint160 graduation; bool above;
    }

    error OnlyLaunchpad();
    error InvalidLaunch();
    error InvalidGraduation();
    error DeveloperBuyUnavailable();

    constructor(address launchpad_, PancakeV1InfinityLaunchFactory factory_,
        PancakeV1InfinityPoolBootstrapper bootstrapper_, IPancakeV1InfinityHookEngine hook_,
        IPancakeV1InfinityDeveloperBuy buyExecutor_) {
        if (launchpad_ == address(0) || address(factory_).code.length == 0
            || address(bootstrapper_).code.length == 0 || address(hook_).code.length == 0
            || address(buyExecutor_) == address(0)
            || factory_.tokenLaunchpad() != launchpad_
            || address(bootstrapper_.hook()) != address(hook_)
            || address(hook_.poolManager()) != address(IPancakeV1InfinityLaunchpad(launchpad_).poolManager())
            || buyExecutor_.launchpad() != launchpad_
            || (buyExecutor_.engine() != address(0) && buyExecutor_.engine() != address(this))
            || buyExecutor_.poolManager() != address(hook_.poolManager())
            || buyExecutor_.hook() != address(hook_)) revert InvalidLaunch();
        launchpad = launchpad_; factory = factory_; bootstrapper = bootstrapper_; hook = hook_;
        developerBuyExecutor = buyExecutor_;
    }

    /// @notice Reciprocal graph attestation used by the storage-safe
    /// launchpad successor initializer.
    function validateLaunchpad(address launchpad_) external view returns (bool) {
        return launchpad_ == launchpad && factory.validateGraph(launchpad_, address(this))
            && address(hook).code.length != 0 && hook.frozen()
            && hook.registrar() == address(this);
    }

    function launch(address creator, bytes calldata encoded) external payable returns (address token) {
        if (msg.sender != launchpad || creator == address(0)) revert OnlyLaunchpad();
        uint256 fee = IPancakeV1InfinityLaunchpad(launchpad).launchFee();
        if (msg.value != fee) revert InvalidLaunch();
        (token,) = _launch(creator, encoded, fee);
    }

    function launchAndBuy(address creator, bytes calldata encoded)
        external payable returns (address token, uint256 projectAmountOut) {
        if (msg.sender != launchpad || creator == address(0)
            || address(developerBuyExecutor) == address(0)) revert DeveloperBuyUnavailable();
        (bytes memory launchEncoded, bytes memory buyEncoded) = abi.decode(encoded, (bytes, bytes));
        if (launchEncoded.length == 0) {
            (token, buyEncoded) = abi.decode(buyEncoded, (address, bytes));
            projectAmountOut = developerBuyExecutor.execute{value: msg.value}(
                token, creator, block.timestamp + 30 minutes, buyEncoded);
            return (token, projectAmountOut);
        }
        uint256 fee = IPancakeV1InfinityLaunchpad(launchpad).launchFee();
        if (msg.value <= fee) revert InvalidLaunch();
        uint256 launchDeadline;
        (token, launchDeadline) = _launch(creator, launchEncoded, fee);
        projectAmountOut = developerBuyExecutor.execute{value: msg.value - fee}(
            token, creator, launchDeadline, buyEncoded);
    }

    function _launch(address creator, bytes memory encoded, uint256 fee)
        internal returns (address token, uint256 launchDeadline) {
        if (!factory.frozen() || !hook.frozen() || factory.engine() != address(this)
            || hook.registrar() != address(this)) revert InvalidLaunch();
        Params memory p = abi.decode(encoded, (Params));
        if (block.timestamp > p.deadline || p.allocations.length == 0
            || p.allocations.length > 5 || p.openingData.length != p.allocations.length) revert InvalidLaunch();
        launchDeadline = p.deadline;
        (string memory name, string memory symbol, string memory uri, bytes32 hash) =
            abi.decode(p.identityData, (string,string,string,bytes32));
        PancakeV1InfinityLaunchFactory.Identity memory identity =
            PancakeV1InfinityLaunchFactory.Identity(creator,name,symbol,uri,hash);
        uint256 protection = p.sniperProtection ? p.protectionBlocks : 0;
        if ((!p.sniperProtection && p.protectionBlocks != 0) || protection > 64) revert InvalidLaunch();
        address lock; address holderVault;
        if (p.mode == IPancakeV1InfinityHookEngine.FeeMode.HOLDER_QUOTE) {
            (token,lock,holderVault) = factory.deployHolder(identity,p.userSalt,protection,
                p.holderExcluded,_quotes(p.allocations));
            hook.schedulePolicy(token,p.mode,p.feeBps,holderVault,p.policyEffectiveAt);
        } else {
            (token,lock) = factory.deployStandard(identity,p.userSalt,protection);
            address destination;
            if (p.mode == IPancakeV1InfinityHookEngine.FeeMode.CREATOR_QUOTE
                || p.mode == IPancakeV1InfinityHookEngine.FeeMode.FEE_SHARING_QUOTE) {
                destination = _modeVault(token, p);
            } else if (p.mode == IPancakeV1InfinityHookEngine.FeeMode.NONE
                || p.mode == IPancakeV1InfinityHookEngine.FeeMode.BURN_PROJECT) {
                if (p.mode == IPancakeV1InfinityHookEngine.FeeMode.NONE && p.modeData.length != 0
                    || p.mode == IPancakeV1InfinityHookEngine.FeeMode.BURN_PROJECT && p.modeData.length != 0) revert InvalidLaunch();
                destination = p.mode == IPancakeV1InfinityHookEngine.FeeMode.BURN_PROJECT
                    ? address(0x000000000000000000000000000000000000dEaD) : address(0);
            } else revert InvalidLaunch();
            hook.schedulePolicy(token,p.mode,p.feeBps,destination,p.policyEffectiveAt);
        }
        uint256 totalWeight;
        uint256 allocated;
        for (uint256 i; i < p.allocations.length; ++i) {
            totalWeight += p.allocations[i].weightBps;
            if (i != 0 && p.allocations[i].quoteToken <= p.allocations[i-1].quoteToken) revert InvalidLaunch();
            Opening memory o = _opening(p.allocations[i],p.openingData[i]);
            uint256 amount = i + 1 == p.allocations.length ? 1_000_000_000 ether - allocated
                : uint256(1_000_000_000 ether) * uint256(p.allocations[i].weightBps) / 10_000;
            allocated += amount;
            IERC20(token).safeTransfer(address(bootstrapper), amount);
            (bytes32 pid,) = bootstrapper.initializePool(token,p.allocations[i].quoteToken,
                amount,p.deadline,lock,o.opening,o.lower,o.upper,hook.getHooksRegistrationBitmap());
            bool project0 = token < p.allocations[i].quoteToken;
            bytes32 parameters = bytes32(uint256(hook.getHooksRegistrationBitmap())
                | (uint256(uint24(uint24(200))) << 16));
            PancakeV1PoolKey memory key = PancakeV1PoolKey(
                PancakeV1Currency.wrap(project0 ? token : p.allocations[i].quoteToken),
                PancakeV1Currency.wrap(project0 ? p.allocations[i].quoteToken : token),
                IPancakeV1Hooks(address(hook)), IPancakeV1CLPoolManager(IPancakeV1InfinityLaunchpad(launchpad).poolManager()),
                10_000, parameters);
            bool above = token < p.allocations[i].quoteToken;
            if (o.above != above) revert InvalidGraduation();
            hook.registerPool(key,token,p.allocations[i].quoteToken,o.graduation,above);
            IPancakeV1InfinityLaunchpad(launchpad).recordInfinityPool(token,p.allocations[i].quoteToken,
                pid,p.allocations[i].weightBps);
        }
        if (totalWeight != 10_000) revert InvalidLaunch();
        (bool ok,) = payable(IPancakeV1InfinityLaunchpad(launchpad).launchFeeRecipient()).call{value: fee}("");
        if (!ok) revert InvalidLaunch();
    }

    function _opening(Allocation memory a, bytes memory data) private view returns (Opening memory o) {
        (o.decimals,o.opening,o.lower,o.upper,o.observed,o.evidence,o.graduation,o.above) =
            abi.decode(data,(uint8,uint160,int24,int24,uint256,bytes32,uint160,bool));
        uint8 d = IERC20Metadata(a.quoteToken).decimals();
        if (d != o.decimals || o.observed > block.timestamp || block.timestamp-o.observed > 30 minutes
            || o.opening < TickMath.MIN_SQRT_PRICE || o.opening >= TickMath.MAX_SQRT_PRICE
            || o.graduation < TickMath.MIN_SQRT_PRICE || o.graduation >= TickMath.MAX_SQRT_PRICE
            || o.lower >= o.upper || o.lower % 200 != 0 || o.upper % 200 != 0) revert InvalidLaunch();
        uint160 lo=TickMath.getSqrtPriceAtTick(o.lower); uint160 hi=TickMath.getSqrtPriceAtTick(o.upper);
        if (o.opening != lo && o.opening != hi
            || (o.above ? o.graduation <= o.opening : o.graduation >= o.opening)) revert InvalidGraduation();
    }

    function _quotes(Allocation[] memory a) private pure returns (address[] memory q) {
        q = new address[](a.length);
        for (uint256 i; i < a.length; ++i) q[i] = a[i].quoteToken;
    }

    function _modeVault(address token, Params memory p) private returns (address destination) {
        if (p.mode == IPancakeV1InfinityHookEngine.FeeMode.CREATOR_QUOTE) {
            (address recipient) = abi.decode(p.modeData, (address));
            destination = factory.deployCreatorVault(token, recipient, p.feeBps);
        } else {
            (PancakeV1FeeSharingVault.Recipient[] memory recipients, address verifier) =
                abi.decode(p.modeData, (PancakeV1FeeSharingVault.Recipient[], address));
            destination = factory.deploySharingVault(token, recipients, verifier, p.feeBps);
        }
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {PancakeV1HolderToken} from "./PancakeV1HolderToken.sol";
import {PancakeV1InfinityCreationDeployers} from "./PancakeV1InfinityCreationDeployers.sol";
import {PancakeV1HolderDistributionVault} from "./PancakeV1HolderDistributionVault.sol";
import {PancakeV1FeeSharingVault} from "./PancakeV1FeeSharingVault.sol";
interface IPancakeV1InfinityVaultDeployer {
    function admin() external view returns(address);
    function engine() external view returns(address);
    function hook() external view returns(address);
    function creator(address,address,uint16) external returns(address);
    function sharing(address,PancakeV1FeeSharingVault.Recipient[] calldata,address,uint16) external returns(address);
}

interface IPancakeV1InfinityHookFactory {
    function addressOf() external view returns (address);
    function poolManager() external view returns (address);
}
interface IPancakeV1InfinityManager { function vault() external view returns (address); }
interface IPancakeV1InfinityGraphEngine {
    function launchpad() external view returns (address);
    function factory() external view returns (address);
    function hook() external view returns (address);
}

/// @notice CREATE2 factory for the hooked Infinity release. Standard tokens
/// use the existing immutable token; holder launches use a token/vault pair
/// whose vault is bound before the initial mint.
contract PancakeV1InfinityLaunchFactory {
    address public immutable admin;
    address public immutable launchpad;
    address public engine;
    address public immutable tokenLaunchpad;
    address public immutable vault;
    address public immutable positionManager;
    address public immutable hook;
    IPancakeV1InfinityVaultDeployer public immutable vaultDeployer;
    PancakeV1InfinityCreationDeployers public immutable creationDeployers;
    bool public frozen;
    mapping(address => mapping(uint8 => mapping(address => bool))) public attestedVault;

    error OnlyLaunchpad();
    error Occupied();
    error InvalidConfiguration();
    error AttestationAuthority();
    event HolderDeployed(address indexed token, address indexed lock, address indexed holderVault);
    event VaultAttested(address indexed project, uint8 indexed mode, address indexed vault);

    struct Identity {
        address creator;
        string name;
        string symbol;
        string metadataURI;
        bytes32 metadataHash;
    }

    constructor(address admin_, address tokenLaunchpad_, address vault_, address positionManager_, address hook_,
        IPancakeV1InfinityVaultDeployer vaultDeployer_, PancakeV1InfinityCreationDeployers creationDeployers_) {
        if (admin_ == address(0) || tokenLaunchpad_ == address(0) || vault_.code.length == 0 || positionManager_.code.length == 0
            || hook_.code.length == 0 || address(vaultDeployer_).code.length == 0
            || vaultDeployer_.hook() != hook_ || vaultDeployer_.admin() != admin_
            || address(creationDeployers_).code.length == 0 || creationDeployers_.admin() != admin_
            || creationDeployers_.positionManager() != positionManager_) revert InvalidConfiguration();
        admin = admin_;
        launchpad = tokenLaunchpad_;
        tokenLaunchpad = tokenLaunchpad_;
        vault = vault_;
        positionManager = positionManager_;
        hook = hook_;
        vaultDeployer = vaultDeployer_;
        creationDeployers = creationDeployers_;
    }

    function bindEngine(address engine_) external {
        if (msg.sender != admin || frozen || engine_ == address(0) || engine_.code.length == 0) {
            revert AttestationAuthority();
        }
        (bool ok, bytes memory data) = engine_.staticcall(abi.encodeWithSignature("factory()"));
        if (!ok || data.length < 32 || abi.decode(data, (address)) != address(this)) revert InvalidConfiguration();
        (ok, data) = engine_.staticcall(abi.encodeWithSignature("hook()"));
        if (!ok || data.length < 32 || abi.decode(data, (address)) != hook) revert InvalidConfiguration();
        // The protected release coordinator binds these two creation helpers
        // to this factory before this final graph edge is frozen.  Requiring
        // the reciprocal identity here prevents a helper from being swapped
        // after activation without allowing the factory to self-authorize a
        // helper binding.
        if (creationDeployers.engine() != address(this)
            || vaultDeployer.engine() != address(this)) revert InvalidConfiguration();
        engine = engine_;
        frozen = true;
    }

    /// @notice Compact reciprocal graph check consumed by the storage-safe
    /// launchpad successor initializer.
    function validateGraph(address launchpad_, address engine_) external view returns (bool) {
        if (!frozen || engine_ != engine || tokenLaunchpad != launchpad_
            || IPancakeV1InfinityGraphEngine(engine_).launchpad() != launchpad_
            || IPancakeV1InfinityGraphEngine(engine_).factory() != address(this)
            || IPancakeV1InfinityGraphEngine(engine_).hook() != hook
            || creationDeployers.engine() != address(this)
            || vaultDeployer.engine() != address(this)) return false;
        return true;
    }

    function deployStandard(Identity calldata i, bytes32 salt, uint256 protectionBlocks)
        external returns (address token, address lock) {
        if (!frozen || msg.sender != engine) revert OnlyLaunchpad();
        (token, lock) = predictStandard(i, salt, protectionBlocks);
        if (token.code.length != 0 || lock.code.length != 0) revert Occupied();
        lock = creationDeployers.lock(_lockSalt(i));
        Identity memory m = i;
        token = _deployStandardToken(m, salt, lock, protectionBlocks);
    }

    /// @notice Predicts the exact standard Infinity token and lock addresses.
    /// The user salt is creator-bound by _tokenSalt but is otherwise unrestricted:
    /// vanity policy (if any) belongs to the website, never this factory.
    function predictStandard(Identity calldata i, bytes32 salt, uint256 protectionBlocks)
        public view returns (address token, address lock) {
        lock = creationDeployers.predictLock(_lockSalt(i));
        token = creationDeployers.predictStandard(
            _tokenSalt(i.creator, salt), i.name, i.symbol, i.metadataURI, i.metadataHash,
            lock, i.creator, engine, protectionBlocks
        );
    }

    function _deployStandardToken(Identity memory i, bytes32 salt, address lock, uint256 protectionBlocks)
        private returns (address token) {
        return creationDeployers.standard(_tokenSalt(i.creator, salt), i.name, i.symbol, i.metadataURI,
            i.metadataHash, lock, i.creator, engine, protectionBlocks);
    }

    function deployHolder(Identity calldata i, bytes32 salt, uint256 protectionBlocks,
        address[] calldata excluded, address[] calldata assets)
        external returns (address token, address lock, address holderVault) {
        if (!frozen || msg.sender != engine) revert OnlyLaunchpad();
        (token, lock) = predictHolder(i, salt, protectionBlocks);
        if (token.code.length != 0 || lock.code.length != 0) revert Occupied();
        lock = creationDeployers.lock(_lockSalt(i));
        token = _deployHolderToken(i, salt, lock, protectionBlocks);
        holderVault = _deployHolderVault(token, excluded, lock);
        _attest(token, 4, holderVault);
        for (uint256 i; i < assets.length; ++i) {
            PancakeV1HolderDistributionVault(holderVault).registerAsset(assets[i]);
        }
        creationDeployers.bind(token, holderVault);
        emit HolderDeployed(token, lock, holderVault);
    }

    /// @notice Predicts the exact holder-token address before vault binding.
    function predictHolder(Identity calldata i, bytes32 salt, uint256 protectionBlocks)
        public view returns (address token, address lock) {
        lock = creationDeployers.predictLock(_lockSalt(i));
        token = _predictHolderToken(i, salt, lock, protectionBlocks);
    }

    function attestVault(address project, uint8 mode, address vault_) external {
        if (!frozen || msg.sender != engine || project == address(0) || vault_.code.length == 0) revert AttestationAuthority();
        _attest(project, mode, vault_);
    }
    function deployCreatorVault(address project, address recipient, uint16 feeBps)
        external returns (address vault_) {
        if (!frozen || msg.sender != engine || recipient == address(0)) revert AttestationAuthority();
        vault_ = vaultDeployer.creator(project, recipient, feeBps);
        _attest(project, 1, vault_);
    }
    function deploySharingVault(address project, PancakeV1FeeSharingVault.Recipient[] calldata recipients,
        address verifier, uint16 feeBps) external returns (address vault_) {
        if (!frozen || msg.sender != engine || verifier == address(0)) revert AttestationAuthority();
        vault_ = vaultDeployer.sharing(project, recipients, verifier, feeBps);
        _attest(project, 3, vault_);
    }
    function verifyVault(address project, uint8 mode, address vault_) external view returns (bool) {
        return attestedVault[project][mode][vault_];
    }
    function _attest(address project, uint8 mode, address vault_) private {
        if (PancakeV1HolderDistributionVault(vault_).projectToken() != project
            || PancakeV1HolderDistributionVault(vault_).hook() != hook) revert InvalidConfiguration();
        attestedVault[project][mode][vault_] = true;
        emit VaultAttested(project, mode, vault_);
    }

    function _deployHolderToken(Identity calldata i, bytes32 salt, address lock, uint256 protectionBlocks)
        private returns (address token) {
        return creationDeployers.holder(_tokenSalt(i.creator, salt), i.name, i.symbol, i.metadataURI,
            i.metadataHash, lock, i.creator, engine, protectionBlocks);
    }

    function _predictHolderToken(Identity calldata i, bytes32 salt, address lock, uint256 protectionBlocks)
        private view returns (address token) {
        return creationDeployers.predictHolder(_tokenSalt(i.creator, salt), i.name, i.symbol,
            i.metadataURI, i.metadataHash, lock, i.creator, engine, protectionBlocks);
    }

    function _deployHolderVault(address token, address[] calldata excluded, address lock)
        private returns (address) {
        address manager = _manager();
        (bool ok, bytes memory data) = manager.staticcall(
            abi.encodeWithSelector(IPancakeV1InfinityManager.vault.selector));
        address custody = ok && data.length >= 32 ? abi.decode(data, (address)) : manager;
        uint256 count = 1;
        if (manager != engine) ++count;
        if (custody != engine && custody != manager) ++count;
        if (positionManager != engine && positionManager != manager && positionManager != custody) ++count;
        if (lock != engine && lock != manager && lock != custody && lock != positionManager) ++count;
        if (tokenLaunchpad != engine && tokenLaunchpad != manager && tokenLaunchpad != custody && tokenLaunchpad != positionManager && tokenLaunchpad != lock) ++count;
        for (uint256 i; i < excluded.length; ++i) {
            if (!_forced(excluded[i], manager, custody, lock, token) && !_contains(excluded, i, excluded[i])) ++count;
        }
        address[] memory all = new address[](count);
        all[0] = engine;
        uint256 n = 1;
        if (manager != engine) all[n++] = manager;
        if (custody != engine && custody != manager) all[n++] = custody;
        if (positionManager != engine && positionManager != manager && positionManager != custody) all[n++] = positionManager;
        if (lock != engine && lock != manager && lock != custody && lock != positionManager) all[n++] = lock;
        if (tokenLaunchpad != engine && tokenLaunchpad != manager && tokenLaunchpad != custody && tokenLaunchpad != positionManager && tokenLaunchpad != lock) all[n++] = tokenLaunchpad;
        for (uint256 i; i < excluded.length; ++i) {
            if (!_forced(excluded[i], manager, custody, lock, token) && !_contains(excluded, i, excluded[i])) all[n++] = excluded[i];
        }
        return address(new PancakeV1HolderDistributionVault(token, hook, address(this), all));
    }

    function _forced(address a, address manager, address custody, address lock, address token) private view returns (bool) {
        return a == address(0) || a == 0x000000000000000000000000000000000000dEaD
            || a == address(this) || a == engine || a == manager || a == custody || a == positionManager
            || a == lock || a == tokenLaunchpad || a == token;
    }
    function _manager() private view returns (address manager) {
        (bool ok, bytes memory data) = hook.staticcall(abi.encodeWithSelector(
            IPancakeV1InfinityHookFactory.poolManager.selector));
        manager = ok && data.length >= 32 ? abi.decode(data, (address)) : positionManager;
    }
    function _contains(address[] calldata a, uint256 end, address value) private pure returns (bool) {
        for (uint256 i; i < end; ++i) if (a[i] == value) return true;
        return false;
    }

    function predictLock(Identity calldata i) external view returns (address) {
        return creationDeployers.predictLock(_lockSalt(i));
    }

    function _lockSalt(Identity calldata i) private pure returns (bytes32) {
        return keccak256(abi.encode(keccak256("PANCAKE_V1_INFINITY_LOCK"), i.creator, i.name,
            i.symbol, i.metadataURI, i.metadataHash));
    }
    function _tokenSalt(address creator, bytes32 salt) private pure returns (bytes32) {
        return keccak256(abi.encode(keccak256("PANCAKE_V1_INFINITY_TOKEN"), creator, salt));
    }
    function _create2(bytes32 salt, bytes32 hash) private view returns (address) {
        return address(uint160(uint256(keccak256(abi.encodePacked(
            bytes1(0xff), address(this), salt, hash
        )))));
    }
}

contracts/pancake-v1/PancakeV1InfinityNf.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {
    PancakeV1InfinityDirectQuoteDeveloperBuyExecutor,
    IPancakeV1DirectBuyHook,
    IPancakeV1DirectBuyAdapter,
    IPancakeV1DirectBuyPermit2
} from "./PancakeV1InfinityDirectQuoteDeveloperBuyExecutor.sol";
import {IPancakeV1CLPoolManager} from "./PancakeV1InfinityHookTypes.sol";

interface IInfinityNftDirectSource {
    function launchInfinityNftFor(address creator, bytes calldata encoded)
        external payable returns (address project);
}

/// @notice Existing-proxy NFT counterpart of the authenticated direct quote
/// coordinator. Reuses the legacy exact-input adapter/route checks unchanged;
/// only its launch entrypoint differs.
contract PancakeV1InfinityNftDirectQuoteCoordinator is PancakeV1InfinityDirectQuoteDeveloperBuyExecutor {
    address public immutable engine;
    constructor(address proxy, address module, IPancakeV1CLPoolManager manager_, IPancakeV1DirectBuyHook hook_,
        IPancakeV1DirectBuyAdapter adapter_, IPancakeV1DirectBuyPermit2 permit2_)
        PancakeV1InfinityDirectQuoteDeveloperBuyExecutor(
            proxy, manager_, hook_, adapter_, permit2_
        )
    {
        if (module == address(0)) revert InvalidBuy();
        engine = module;
    }

    function launchAndBuy(bytes calldata launchData, bytes calldata encodedPlan)
        external payable override returns (address project)
    {
        project = IInfinityNftDirectSource(launchpad).launchInfinityNftFor{value: msg.value}(
            msg.sender, launchData
        );
        this.execute(project, msg.sender, encodedPlan);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {PancakeV1NFTProxyFactory} from "./PancakeV1NFTProxyFactory.sol";
import {PancakeV1InfinityPoolBootstrapper} from "./PancakeV1InfinityPoolBootstrapper.sol";
import {PancakeV1PoolKey, PancakeV1Currency, IPancakeV1Hooks, IPancakeV1CLPoolManager} from "./PancakeV1InfinityHookTypes.sol";

interface IIntegratedNftHook {
    function poolManager() external view returns (address);
    function frozen() external view returns (bool);
    function registrar() external view returns (address);
    function attestor() external view returns (address);
    function getHooksRegistrationBitmap() external view returns (uint16);
    function schedulePolicy(address, uint8, uint16, address, uint64) external returns (uint64);
    function registerPool(PancakeV1PoolKey calldata, address, address, uint160, bool) external;
    function poolId(PancakeV1PoolKey calldata) external pure returns (bytes32);
}

interface IIntegratedNftBuy {
    function launchpad() external view returns (address);
    function engine() external view returns (address);
    function hook() external view returns (address);
    function poolManager() external view returns (address);
    function execute(address, address, uint256, bytes calldata) external payable returns (uint256);
}
interface IIntegratedNftTokenBinding {
    function launchpad() external view returns (address);
    function poolManager() external view returns (address);
}
interface IIntegratedNftCollectionBinding {
    function projectToken() external view returns (address);
    function hook() external view returns (address);
}

interface IIntegratedNftProxy {
    function launchFee() external view returns (uint256);
    function launchFeeRecipient() external view returns (address);
    function recordInfinityNftPool(address, address, bytes32, uint16,
        uint256, uint256, int24, int24, uint256, uint8) external;
    function releaseInfinityNftSupply(address) external;
}

/// @notice Only the existing Infinity proxy may invoke the separate NFT engine.
/// Historical mode engines, hooks and PoolIds are not replaced.
contract PancakeV1InfinityNftLaunchModule is ReentrancyGuard {
    using SafeERC20 for IERC20;

    struct Allocation { address quoteToken; uint16 weightBps; }
    struct Params {
        bytes identityData; Allocation[] allocations; bytes[] openingData; uint256 deadline;
        bytes32 userSalt; bool sniperProtection; uint256 protectionBlocks; uint8 mode;
        uint16 feeBps; bytes modeData; uint64 policyEffectiveAt; address[] holderExcluded;
    }
    struct Opening {
        uint8 decimals; uint160 opening; int24 lower; int24 upper; uint256 observed;
        bytes32 evidence; uint160 graduation; bool above;
    }
    struct RegisteredPool {
        address quote; bytes32 id; uint16 weight; uint256 positionId;
        uint256 projectAmount; int24 lower; int24 upper; uint256 quotePriceE8; uint8 quoteDecimals;
    }

    address public immutable launchpad;
    PancakeV1NFTProxyFactory public immutable factory;
    IIntegratedNftHook public immutable hook;
    PancakeV1InfinityPoolBootstrapper public immutable bootstrapper;
    IIntegratedNftBuy public immutable developerBuyExecutor;
    mapping(address => RegisteredPool[]) private _registeredPools;
    error InvalidLaunch();
    event NFTProjectLaunched(address indexed projectToken, address indexed creator, address indexed collection);

    constructor(address proxy_, PancakeV1NFTProxyFactory factory_, IIntegratedNftHook hook_,
        PancakeV1InfinityPoolBootstrapper bootstrapper_, IIntegratedNftBuy executor_) {
        if (proxy_.code.length == 0 || address(factory_).code.length == 0
            || address(hook_).code.length == 0 || address(bootstrapper_).code.length == 0
            || factory_.hook() != address(hook_) || address(bootstrapper_.hook()) != address(hook_)
            || address(bootstrapper_.manager()) != hook_.poolManager()
            || executor_.launchpad() != proxy_ || executor_.engine() != address(this)
            || executor_.hook() != address(hook_)
            || executor_.poolManager() != hook_.poolManager()
            || factory_.creationDeployers().tokenLaunchpad() != proxy_)
            revert InvalidLaunch();
        launchpad = proxy_;
        factory = factory_;
        hook = hook_;
        bootstrapper = bootstrapper_;
        developerBuyExecutor = executor_;
    }

    function validatePool(address project, address quote, bytes32 id, uint16 weight,
        uint256 positionId, uint256 projectAmount, int24 lower, int24 upper,
        uint256 quotePriceE8, uint8 quoteDecimals) external view returns (bool)
    {
        if (msg.sender != launchpad || factory.collectionOf(project) == address(0)) return false;
        RegisteredPool[] storage records = _registeredPools[project];
        for (uint256 i; i < records.length; ++i)
            if (records[i].quote == quote && records[i].id == id
                && records[i].weight == weight && records[i].positionId == positionId
                && records[i].projectAmount == projectAmount && records[i].lower == lower
                && records[i].upper == upper && records[i].quotePriceE8 == quotePriceE8
                && records[i].quoteDecimals == quoteDecimals)
                return true;
        return false;
    }

    function validateSupply(address project) external view returns (bool) {
        if (msg.sender != launchpad || project.code.length == 0) return false;
        address collection = factory.collectionOf(project);
        return collection.code.length != 0
            && factory.creationDeployers().tokenLaunchpad() == launchpad
            && IIntegratedNftCollectionBinding(collection).projectToken() == project
            && IIntegratedNftCollectionBinding(collection).hook() == address(hook)
            && IIntegratedNftTokenBinding(project).launchpad() == launchpad
            // The token's poolManager is the CL manager's *vault* (its
            // transfer-gated settlement address), as wired by the existing
            // creation deployer. It is not the CL manager contract itself.
            && IIntegratedNftTokenBinding(project).poolManager() == factory.creationDeployers().vault();
    }

    function launch(address creator, bytes calldata encoded)
        external payable nonReentrant returns (address token)
    {
        if (msg.sender != launchpad || creator == address(0)
            || msg.value != IIntegratedNftProxy(launchpad).launchFee()) revert InvalidLaunch();
        token = _launch(creator, encoded);
    }

    function launchAndBuy(address creator, bytes calldata encoded)
        external payable nonReentrant returns (address token, uint256 output)
    {
        if (msg.sender != launchpad || creator == address(0)
            || msg.value <= IIntegratedNftProxy(launchpad).launchFee()) revert InvalidLaunch();
        (bytes memory launchData, bytes memory buyPlan) = abi.decode(encoded, (bytes, bytes));
        if (launchData.length == 0) revert InvalidLaunch();
        Params memory p = abi.decode(launchData, (Params));
        token = _launch(creator, launchData);
        output = developerBuyExecutor.execute{
            value: msg.value - IIntegratedNftProxy(launchpad).launchFee()
        }(token, creator, p.deadline, buyPlan);
    }

    function _launch(address creator, bytes memory encoded) private returns (address token) {
        if (!hook.frozen() || hook.registrar() != address(this)
            || hook.attestor() != address(factory) || factory.engine() != address(this))
            revert InvalidLaunch();
        Params memory p = abi.decode(encoded, (Params));
        // ABI decoders accept trailing garbage and overlapping offsets. NFT
        // launches require the precise canonical tuple, not a parser prefix.
        if (keccak256(encoded) != keccak256(abi.encode(p))) revert InvalidLaunch();
        if (p.mode != 5 || p.feeBps < 100 || p.feeBps > 1000 || p.feeBps % 100 != 0
            || p.policyEffectiveAt != 0 || p.holderExcluded.length != 0
            || p.sniperProtection || p.protectionBlocks != 0 || p.deadline < block.timestamp
            || p.deadline > type(uint48).max || p.allocations.length == 0
            || p.allocations.length > 5 || p.openingData.length != p.allocations.length)
            revert InvalidLaunch();
        (string memory name, string memory symbol, string memory uri, bytes32 hash) =
            abi.decode(p.identityData, (string, string, string, bytes32));
        address[] memory quotes = new address[](p.allocations.length);
        uint256 totalWeight;
        for (uint256 i; i < quotes.length; ++i) {
            quotes[i] = p.allocations[i].quoteToken;
            if (p.allocations[i].weightBps == 0 || (i != 0 && quotes[i] <= quotes[i - 1]))
                revert InvalidLaunch();
            totalWeight += p.allocations[i].weightBps;
        }
        if (totalWeight != 10000) revert InvalidLaunch();
        address lock;
        address collection;
        (token, lock, collection) = factory.deploy(
            PancakeV1NFTProxyFactory.Identity(creator, name, symbol, uri, hash),
            p.userSalt, p.modeData, quotes
        );
        hook.schedulePolicy(token, 5, p.feeBps, collection, 0);
        IIntegratedNftProxy(launchpad).releaseInfinityNftSupply(token);
        uint256 allocated;
        for (uint256 i; i < quotes.length; ++i) {
            Opening memory o = abi.decode(p.openingData[i], (Opening));
            bool project0 = token < quotes[i];
            if (o.decimals != IERC20Metadata(quotes[i]).decimals()
                || o.observed > block.timestamp || block.timestamp - o.observed > 30 minutes
                || o.lower >= o.upper || o.lower % 200 != 0 || o.upper % 200 != 0
                || o.lower < TickMath.MIN_TICK || o.upper > TickMath.MAX_TICK
                || o.above != project0
                || o.graduation < TickMath.MIN_SQRT_PRICE || o.graduation >= TickMath.MAX_SQRT_PRICE
                || (project0 ? o.graduation <= o.opening : o.graduation >= o.opening)
                || o.opening != TickMath.getSqrtPriceAtTick(project0 ? o.lower : o.upper))
                revert InvalidLaunch();
            uint256 amount = i + 1 == quotes.length ? 1_000_000_000 ether - allocated
                : uint256(1_000_000_000 ether) * p.allocations[i].weightBps / 10000;
            allocated += amount;
            IERC20(token).safeTransfer(address(bootstrapper), amount);
            (bytes32 id, uint256 positionId) = bootstrapper.initializePool(
                token, quotes[i], amount, p.deadline, lock,
                o.opening, o.lower, o.upper, hook.getHooksRegistrationBitmap()
            );
            PancakeV1PoolKey memory key = PancakeV1PoolKey(
                PancakeV1Currency.wrap(project0 ? token : quotes[i]),
                PancakeV1Currency.wrap(project0 ? quotes[i] : token),
                IPancakeV1Hooks(address(hook)), IPancakeV1CLPoolManager(hook.poolManager()),
                10000, bytes32(uint256(hook.getHooksRegistrationBitmap()) | (uint256(200) << 16))
            );
            if (hook.poolId(key) != id) revert InvalidLaunch();
            hook.registerPool(key, token, quotes[i], o.graduation, o.above);
            _registeredPools[token].push(RegisteredPool(quotes[i], id, p.allocations[i].weightBps,
                positionId, amount, o.lower, o.upper, 0, o.decimals));
            IIntegratedNftProxy(launchpad).recordInfinityNftPool(
                token, quotes[i], id, p.allocations[i].weightBps,
                positionId, amount, o.lower, o.upper, 0, o.decimals
            );
        }
        uint256 residue = IERC20(token).balanceOf(address(this));
        if (residue != 0)
            IERC20(token).safeTransfer(0x000000000000000000000000000000000000dEaD, residue);
        (bool ok,) = payable(IIntegratedNftProxy(launchpad).launchFeeRecipient()).call{
            value: IIntegratedNftProxy(launchpad).launchFee()
        }("");
        if (!ok) revert InvalidLaunch();
        emit NFTProjectLaunched(token, creator, collection);
    }
}

contracts/pancake-v1/PancakeV1InfinityPo.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {LiquidityAmounts} from "@uniswap/v4-periphery/src/libraries/LiquidityAmounts.sol";
import {IV1PoolManager, IV1Permit2, IV1CLPositionManager, IV1Hooks, V1Currency, V1PoolKey} from "./PancakeV1Interfaces.sol";

contract PancakeV1InfinityPoolBootstrapper {
    using SafeERC20 for IERC20;
    IV1PoolManager public immutable manager;
    IV1CLPositionManager public immutable positions;
    IV1Permit2 public immutable permit2;
    IV1Hooks public immutable hook;
    uint24 public constant FEE = 10_000;
    int24 public constant SPACING = 200;

    constructor(IV1PoolManager manager_, IV1CLPositionManager positions_, IV1Permit2 permit2_, IV1Hooks hook_) {
        if (address(manager_).code.length == 0 || address(positions_).code.length == 0
            || address(permit2_).code.length == 0 || address(hook_).code.length == 0
            || address(manager_.vault()).code.length == 0) revert();
        manager = manager_; positions = positions_; permit2 = permit2_; hook = hook_;
    }

    function initializePool(address token, address quote, uint256 amount, uint256 deadline, address lock,
        uint160 opening, int24 lower, int24 upper, uint16 bitmap)
        external returns (bytes32 pid, uint256 positionId) {
        (bool registrarOk, bytes memory registrarData) = address(hook).staticcall(
            abi.encodeWithSignature("registrar()"));
        if (!registrarOk || registrarData.length < 32
            || abi.decode(registrarData, (address)) != msg.sender) revert("CALLER");
        uint256 beforeBalance = IERC20(token).balanceOf(address(this));
        if (beforeBalance != amount) revert("FUNDING");
        permit2.approve(token, address(positions), uint160(amount), uint48(deadline));
        IERC20(token).forceApprove(address(permit2), amount);
        bool projectIs0 = token < quote;
        bytes32 parameters = bytes32((uint256(bitmap)) | (uint256(uint24(uint24(SPACING))) << 16));
        V1PoolKey memory key = V1PoolKey(
            V1Currency.wrap(projectIs0 ? token : quote), V1Currency.wrap(projectIs0 ? quote : token),
            hook, manager, FEE, parameters);
        manager.initialize(key, opening);
        positionId = positions.nextTokenId();
        uint160 lo = TickMath.getSqrtPriceAtTick(lower);
        uint160 hi = TickMath.getSqrtPriceAtTick(upper);
        uint256 liq = projectIs0
            ? LiquidityAmounts.getLiquidityForAmount0(lo, hi, amount)
            : LiquidityAmounts.getLiquidityForAmount1(lo, hi, amount);
        require(liq != 0 && liq <= type(uint128).max, "LIQUIDITY");
        bytes[] memory p = new bytes[](2);
        p[0] = abi.encode(key, lower, upper, uint128(liq),
            uint128(projectIs0 ? amount : 0), uint128(projectIs0 ? 0 : amount), lock, bytes(""));
        p[1] = abi.encode(key.currency0, key.currency1);
        positions.modifyLiquidities(abi.encode(hex"020d", p), deadline);
        permit2.approve(token, address(positions), 0, 0);
        IERC20(token).forceApprove(address(permit2), 0);
        uint256 residue = IERC20(token).balanceOf(address(this));
        if (residue != 0) {
            // Infinity position minting can round liquidity down by a few
            // units. Return that remainder to the launchpad rather than
            // leaving an unrecoverable balance on the bootstrapper.
            IERC20(token).safeTransfer(msg.sender, residue);
        }
        if (IERC20(token).balanceOf(address(this)) != 0) revert("RESIDUE");
        pid = keccak256(abi.encode(key));
    }
}

contracts/pancake-v1/PancakeV1InfinitySw.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {
    PancakeV1Currency,
    PancakeV1PoolKey,
    IPancakeV1CLPoolManager,
    IPancakeV1Hooks,
    IPancakeV1Vault,
    IPancakeV1LockCallback
} from "./PancakeV1InfinityHookTypes.sol";

interface IPancakeV1PostSwapFeeHook {
    function settleUnspecifiedFee() external;
}

/// @notice Direct Pancake Infinity CL settlement adapter.
/// @dev The public Universal Router does not safely settle a positive
/// beforeSwap specified delta on the deployed Infinity Vault. This adapter
/// performs the canonical Vault.lock -> CLPoolManager.swap flow and clears
/// both the caller and hook deltas before the lock returns.
contract PancakeV1InfinitySwapAdapter is IPancakeV1LockCallback {
    using SafeERC20 for IERC20;

    uint24 public constant MAX_HOOK_FEE_BPS = 30;
    uint160 private constant MIN_SQRT_PRICE = 4295128740;
    uint160 private constant MAX_SQRT_PRICE =
        1461446703485210103287273052203988822378723970341;
    uint256 private _entered;

    IPancakeV1CLPoolManager public immutable poolManager;
    IPancakeV1Vault public immutable vault;
    IPancakeV1Hooks public immutable hook;

    error InvalidRoute();
    error OnlyVault();
    error OnlyHook();
    error Reentered();
    error DeadlineExpired();
    error Slippage();
    error Residual(address token);
    error Unsettled();

    struct SwapRequest {
        PancakeV1PoolKey key;
        IPancakeV1CLPoolManager.SwapParams params;
        bytes hookData;
        address payer;
        address recipient;
        uint256 maxInput;
        uint256 deadline;
    }

    constructor(IPancakeV1CLPoolManager manager_, IPancakeV1Hooks hook_) {
        address vault_ = manager_.vault();
        if (address(manager_) == address(0) || vault_ == address(0)
            || address(manager_).code.length == 0 || vault_.code.length == 0
            || address(hook_) == address(0) || address(hook_).code.length == 0) {
            revert InvalidRoute();
        }
        poolManager = manager_;
        vault = IPancakeV1Vault(vault_);
        hook = hook_;
    }

    function executeExactInput(
        PancakeV1PoolKey calldata key,
        bool zeroForOne,
        uint256 amountIn,
        uint256 inputMaximum,
        uint256 amountOutMinimum,
        address payer,
        address recipient,
        uint256 deadline,
        bytes calldata hookData
    ) external returns (uint256 amountOut) {
        if (amountIn == 0 || inputMaximum < amountIn) revert InvalidRoute();
        amountOut = _execute(key, zeroForOne, -int256(amountIn), amountOutMinimum,
            inputMaximum, payer, recipient, deadline, hookData);
    }

    function executeExactOutput(
        PancakeV1PoolKey calldata key,
        bool zeroForOne,
        uint256 amountOut,
        uint256 amountInMaximum,
        address payer,
        address recipient,
        uint256 deadline,
        bytes calldata hookData
    ) external returns (uint256 amountIn) {
        if (amountOut == 0) revert InvalidRoute();
        amountIn = _execute(key, zeroForOne, int256(amountOut), amountInMaximum,
            amountInMaximum, payer, recipient, deadline, hookData);
    }

    function lockAcquired(bytes calldata raw) external returns (bytes memory) {
        if (msg.sender != address(vault)) revert OnlyVault();
        SwapRequest memory request = abi.decode(raw, (SwapRequest));
        PancakeV1Currency input = request.params.zeroForOne
            ? request.key.currency0 : request.key.currency1;
        PancakeV1Currency output = request.params.zeroForOne
            ? request.key.currency1 : request.key.currency0;
        // Fund gross input before the swap. The pool consumes the net specified
        // amount and the hook settles fees from the adapter's remaining input
        // or output credit without creating hook-owned deltas.
        vault.sync(input);
        IERC20(PancakeV1Currency.unwrap(input)).safeTransfer(address(vault), request.maxInput);
        if (vault.settleFor(address(this)) != request.maxInput) revert Unsettled();
        poolManager.swap(request.key, request.params, request.hookData);
        IPancakeV1PostSwapFeeHook(address(hook)).settleUnspecifiedFee();
        // Unspent input belongs to the payer, not the output recipient.
        // Executors must observe this refund to reject partial-fill launches.
        _settle(address(this), input, request.payer);
        _settle(address(this), output, request.recipient);
        if (vault.getUnsettledDeltasCount() != 0) revert Unsettled();
        return "";
    }

    function settleHookFee(address asset, address destination, uint256 amount) external {
        if (msg.sender != address(hook)) revert OnlyHook();
        if (_entered != 1 || asset == address(0) || destination == address(0) || amount == 0) {
            revert InvalidRoute();
        }
        PancakeV1Currency currency = PancakeV1Currency.wrap(asset);
        int256 credit = vault.currencyDelta(address(this), currency);
        if (credit < 0 || uint256(credit) < amount) revert Unsettled();
        vault.take(currency, destination, amount);
    }

    function _execute(
        PancakeV1PoolKey calldata key,
        bool zeroForOne,
        int256 amountSpecified,
        uint256 amountLimit,
        uint256 maxInput,
        address payer,
        address recipient,
        uint256 deadline,
        bytes calldata hookData
    ) private returns (uint256 result) {
        if (_entered != 0) revert Reentered();
        if (block.timestamp > deadline || payer == address(0) || recipient == address(0)
            || address(key.poolManager) != address(poolManager)
            || address(key.hooks) != address(hook)
            || PancakeV1Currency.unwrap(key.currency0) >= PancakeV1Currency.unwrap(key.currency1)
            || key.fee > 30_000) revert InvalidRoute();
        _entered = 1;
        PancakeV1Currency input = zeroForOne ? key.currency0 : key.currency1;
        address inputToken = PancakeV1Currency.unwrap(input);
        uint256 beforeBalance = IERC20(inputToken).balanceOf(address(this));
        if (beforeBalance != 0) revert Residual(inputToken);
        IERC20(inputToken).safeTransferFrom(payer, address(this), maxInput);
        if (IERC20(inputToken).balanceOf(address(this)) != maxInput) revert InvalidRoute();
        address outputToken = PancakeV1Currency.unwrap(zeroForOne ? key.currency1 : key.currency0);
        uint256 beforeOut = IERC20(outputToken).balanceOf(recipient);
        SwapRequest memory request = SwapRequest(
            key,
            IPancakeV1CLPoolManager.SwapParams(
                zeroForOne, amountSpecified, zeroForOne ? MIN_SQRT_PRICE : MAX_SQRT_PRICE
            ),
            hookData, payer, recipient, maxInput, deadline
        );
        vault.lock(abi.encode(request));
        uint256 afterBalance = IERC20(inputToken).balanceOf(address(this));
        if (afterBalance > 0) {
            IERC20(inputToken).safeTransfer(payer, afterBalance);
        }
        if (IERC20(inputToken).balanceOf(address(this)) != 0) revert Residual(inputToken);
        if (amountSpecified < 0) {
            uint256 afterOut = IERC20(outputToken).balanceOf(recipient);
            if (afterOut < beforeOut || afterOut - beforeOut < amountLimit) revert Slippage();
            result = afterOut - beforeOut;
        } else {
            uint256 afterOut = IERC20(outputToken).balanceOf(recipient);
            if (afterOut < beforeOut || afterOut - beforeOut < uint256(amountSpecified)) revert Slippage();
            result = maxInput - afterBalance;
            if (result > amountLimit) revert Slippage();
        }
        _entered = 0;
    }

    function _settle(address settler, PancakeV1Currency currency, address recipient) private {
        int256 delta = vault.currencyDelta(settler, currency);
        address token = PancakeV1Currency.unwrap(currency);
        if (delta < 0) {
            uint256 amount = uint256(-delta);
            vault.sync(currency);
            IERC20(token).safeTransfer(address(vault), amount);
            vault.settleFor(settler);
        } else if (delta > 0) {
            vault.take(currency, settler == address(this) ? recipient : settler, uint256(delta));
        }
    }

    receive() external payable {
        revert InvalidRoute();
    }
}

contracts/pancake-v1/PancakeV1InfinityTo.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
contract PancakeV1InfinityToken is ERC20 {
    uint256 public constant TOTAL_SUPPLY = 1_000_000_000 ether;
    address public immutable launchpad;
    address public immutable poolManager;
    address public immutable positionManager;
    address public immutable locker;
    address public immutable initialBuyRecipient;
    uint256 public immutable launchBlock;
    uint256 public immutable restrictionsEndBlock;
    string private _metadataURI;
    bytes32 public immutable metadataHash;
    constructor(string memory n,string memory s,string memory u,bytes32 h,address lp,address pm,address pos,
        address l,address recipient,address mintTo,uint256 blocks_) ERC20(n,s) {
        launchpad=lp; poolManager=pm; positionManager=pos; locker=l; initialBuyRecipient=recipient;
        launchBlock=block.number; restrictionsEndBlock=block.number+blocks_; _metadataURI=u; metadataHash=h;
        _mint(mintTo,TOTAL_SUPPLY);
    }
    function metadataURI() external view returns(string memory){return _metadataURI;}
    function tokenURI() external view returns(string memory){return _metadataURI;}
    function _update(address from,address to,uint256 value) internal override {
        if(restrictionsEndBlock > launchBlock && block.number<=restrictionsEndBlock&&from!=address(0)&&to!=address(0)
            &&to!=poolManager&&to!=positionManager&&to!=locker&&to!=launchpad) {
            if(from==poolManager){if(block.number==launchBlock&&to!=initialBuyRecipient)revert("LAUNCH_BLOCK");if(value>55_000_000 ether)revert("BUY_CAP");}
            if(balanceOf(to)+value>50_000_000 ether)revert("HOLD_CAP");
        }
        super._update(from,to,value);
    }
}

