contracts/pancake-v1/PancakeV1LaunchpadI.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

interface IInfinityNftModule {
    function launchpad() external view returns (address);
    function hook() external view returns (address);
    function factory() external view returns (address);
    function launch(address creator, bytes calldata encoded) external payable returns (address token);
    function launchAndBuy(address creator, bytes calldata encoded) external payable returns (address token, uint256 output);
    function validatePool(address project, address quote, bytes32 id, uint16 weight,
        uint256 positionId, uint256 projectAmount, int24 lower, int24 upper,
        uint256 quotePriceE8, uint8 quoteDecimals) external view returns (bool);
    function validateSupply(address project) external view returns (bool);
}

interface IInfinityNftCoordinator {
    function launchpad() external view returns (address);
    function engine() external view returns (address);
}

/// @notice Thin UUPS dispatcher installed at the EXISTING launchpad proxy.
/// Legacy selectors delegatecall the PINNED prior implementation, retaining
/// its exact behavior/storage. NFT calls use ordinary calls to a new module.
/// @dev Pin the prior runtime and validate its exact layout before deployment:
/// slot 9 is _pools; slot 0x39 is _infinityEngine. No new storage is appended.
contract PancakeV1LaunchpadInfinityNftUpgradeable is OwnableUpgradeable, UUPSUpgradeable {
    using SafeERC20 for IERC20;
    address public immutable legacyImplementation;
    IInfinityNftModule public immutable nftModule;
    address public immutable nftDirectQuoteCoordinator;
    error InvalidNftRoute();

    constructor(address expectedProxy, address legacy, bytes32 legacyCodeHash,
        IInfinityNftModule module_, address coordinator)
    {
        if (expectedProxy.code.length == 0 || legacy.codehash != legacyCodeHash
            || legacyCodeHash == bytes32(0) || legacy == expectedProxy
            || address(module_).code.length == 0 || module_.launchpad() != expectedProxy
            || module_.hook() == address(0) || module_.factory() == address(0)
            || coordinator.code.length == 0
            || IInfinityNftCoordinator(coordinator).launchpad() != expectedProxy
            || IInfinityNftCoordinator(coordinator).engine() != address(module_))
            revert InvalidNftRoute();
        legacyImplementation = legacy;
        nftModule = module_;
        nftDirectQuoteCoordinator = coordinator;
        _disableInitializers();
    }

    function _authorizeUpgrade(address) internal override onlyOwner {}

    function _mode(bytes calldata encoded) private pure returns (uint256 mode) {
        if (encoded.length < 13 * 32) revert InvalidNftRoute();
        uint256 head;
        assembly { head := calldataload(encoded.offset) }
        if (head % 32 != 0 || head > encoded.length - 12 * 32) revert InvalidNftRoute();
        assembly { mode := calldataload(add(add(encoded.offset, head), 224)) }
    }

    function launchInfinity(bytes calldata encoded) external payable returns (address token) {
        uint256 mode = _mode(encoded);
        if (mode == 5) return nftModule.launch{value: msg.value}(msg.sender, encoded);
        if (mode > 4) revert InvalidNftRoute();
        _delegateLegacy();
    }

    function launchInfinityAndBuy(bytes calldata encoded) external payable {
        (bytes memory launchData, bytes memory buyPlan) = abi.decode(encoded, (bytes, bytes));
        // A buy-only call (empty launchData) is a legacy path.
        if (launchData.length != 0) {
            if (launchData.length < 13 * 32) revert InvalidNftRoute();
            uint256 mode;
            uint256 head;
            assembly { head := mload(add(launchData, 32)) }
            if (head % 32 != 0 || head > launchData.length - 12 * 32) revert InvalidNftRoute();
            assembly { mode := mload(add(add(launchData, 32), add(head, 224))) }
            if (mode == 5) {
                if (keccak256(encoded) != keccak256(abi.encode(launchData, buyPlan)))
                    revert InvalidNftRoute();
                nftModule.launchAndBuy{value: msg.value}(msg.sender, encoded);
                return;
            }
            if (mode > 4) revert InvalidNftRoute();
        }
        _delegateLegacy();
    }

    function launchInfinityNftFor(address creator, bytes calldata encoded)
        external payable returns (address token)
    {
        if (msg.sender != nftDirectQuoteCoordinator || creator == address(0)
            || _mode(encoded) != 5) revert InvalidNftRoute();
        token = nftModule.launch{value: msg.value}(creator, encoded);
    }

    /// @dev New factory mints project supply to the existing proxy because
    /// project tokens are permanently bound to that launchpad address.
    function releaseInfinityNftSupply(address project) external {
        if (msg.sender != address(nftModule) || project == address(0)
            || !nftModule.validateSupply(project)) revert InvalidNftRoute();
        IERC20 token = IERC20(project);
        uint256 supply = 1_000_000_000 ether;
        if (token.balanceOf(address(this)) != supply || token.totalSupply() != supply)
            revert InvalidNftRoute();
        token.safeTransfer(msg.sender, supply);
    }

    /// @dev Keccak mapping layout copied from the compiler-verified deployed
    /// predecessor. Only the pinned NFT module can append, and only after its
    /// registered actual manager PoolKey and factory collection checks pass.
    function recordInfinityNftPool(address project, address quote, bytes32 id, uint16 weight,
        uint256 positionId, uint256 projectAmount, int24 lower, int24 upper,
        uint256 quotePriceE8, uint8 quoteDecimals) external
    {
        if (msg.sender != address(nftModule) || project == address(0)
            || quote == address(0) || id == bytes32(0) || weight == 0 || positionId == 0
            || projectAmount == 0 || lower >= upper
            || !nftModule.validatePool(project, quote, id, weight,
                positionId, projectAmount, lower, upper, quotePriceE8, quoteDecimals))
            revert InvalidNftRoute();
        bytes32 arraySlot = keccak256(abi.encode(project, uint256(9)));
        uint256 ticks = uint256(uint24(lower)) | (uint256(uint24(upper)) << 24);
        assembly {
            let length := sload(arraySlot)
            // Five markets maximum. All destinations are fresh storage.
            if iszero(lt(length, 5)) { revert(0, 0) }
            sstore(arraySlot, add(length, 1))
            mstore(0, arraySlot)
            let base := add(keccak256(0, 32), mul(length, 7))
            sstore(base, or(shl(160, weight), quote))
            sstore(add(base, 1), id)
            sstore(add(base, 2), positionId)
            sstore(add(base, 3), projectAmount)
            sstore(add(base, 4), ticks)
            sstore(add(base, 5), quotePriceE8)
            sstore(add(base, 6), quoteDecimals)
        }
    }

    fallback() external payable { _delegateLegacy(); }
    receive() external payable { _delegateLegacy(); }

    function _delegateLegacy() private {
        address target = legacyImplementation;
        assembly {
            calldatacopy(0, 0, calldatasize())
            let ok := delegatecall(gas(), target, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch ok
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }
}

contracts/pancake-v1/PancakeV1NFTCollect.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Strings} from "@openzeppelin/contracts/utils/Strings.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @notice Final custody and NFT-weighted reward ledger for the isolated NFT release.
/// @dev No owner, upgrades, rescue, mutable assets, NFT redemption or payout signer.
contract PancakeV1NFTCollection is ERC721, ReentrancyGuard {
    using SafeERC20 for IERC20;
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    uint256 public constant ORIGINAL_SUPPLY = 1_000_000_000 ether;
    uint256 public constant PRECISION = 1e27;
    uint256 public constant MAX_BATCH = 50;
    address public immutable projectToken;
    address public immutable hook;
    uint256 public immutable maxSupply;
    uint256 public immutable tokenCost;
    uint256 public totalMinted;
    string public baseURI;
    address[] private _assets;
    mapping(address => bool) public registeredAsset;
    mapping(address => uint256) public rewardIndex;
    mapping(address => uint256) public recorded;
    mapping(address => uint256) public paid;
    mapping(address => mapping(address => uint256)) private _index;
    mapping(address => mapping(address => uint256)) private _earned;
    mapping(address => mapping(address => uint256)) private _fraction;
    bool private _minting;

    error InvalidConfiguration();
    error OnlyHook();
    error InvalidAmount();
    error UnsupportedAsset();
    error UnsupportedTransfer();
    error NoRewards();
    error MintInProgress();

    event Minted(address indexed account, uint256 firstTokenId, uint256 quantity, uint256 projectBurned);
    event FeeRecorded(address indexed asset, uint256 amount);
    event RewardClaimed(address indexed holder, address indexed asset, uint256 amount);

    constructor(address project_, address hook_, string memory name_, string memory symbol_,
        uint256 maximum_, uint256 cost_, string memory uri_, address[] memory assets_)
        ERC721(name_, symbol_)
    {
        bytes memory uri = bytes(uri_);
        bytes memory suffix = bytes("/metadata/");
        if (project_.code.length == 0 || hook_.code.length == 0 || maximum_ == 0
            || cost_ == 0 || maximum_ > (ORIGINAL_SUPPLY - 1) / cost_
            || bytes(name_).length == 0 || bytes(name_).length > 128
            || bytes(symbol_).length == 0 || bytes(symbol_).length > 32
            || uri.length < 18 || uri.length > 256 || assets_.length == 0 || assets_.length > 5)
            revert InvalidConfiguration();
        // Restrict to absolute HTTPS directories; do not allow query/fragment suffix ambiguity.
        if (keccak256(_prefix(uri, 8)) != keccak256(bytes("https://"))
            && keccak256(_prefix(uri, 7)) != keccak256(bytes("ipfs://"))) revert InvalidConfiguration();
        for (uint256 i; i < suffix.length; ++i)
            if (uri[uri.length - suffix.length + i] != suffix[i]) revert InvalidConfiguration();
        for (uint256 i; i < uri.length; ++i)
            if (uint8(uri[i]) <= 32 || uri[i] == "?" || uri[i] == "#" || uri[i] == "\\")
                revert InvalidConfiguration();
        projectToken = project_;
        hook = hook_;
        maxSupply = maximum_;
        tokenCost = cost_;
        baseURI = uri_;
        for (uint256 i; i < assets_.length; ++i) {
            address asset = assets_[i];
            if (asset.code.length == 0 || asset == project_ || registeredAsset[asset])
                revert InvalidConfiguration();
            registeredAsset[asset] = true;
            _assets.push(asset);
        }
    }

    function _prefix(bytes memory value, uint256 size) private pure returns (bytes memory out) {
        out = new bytes(size);
        for (uint256 i; i < size; ++i) out[i] = value[i];
    }

    function assets() external view returns (address[] memory) { return _assets; }
    function rewardsActive() external view returns (bool) {
        if (_minting) revert MintInProgress();
        return totalMinted != 0;
    }
    function previewURI(uint256 id) public view returns (string memory) {
        if (id == 0 || id > maxSupply) revert InvalidAmount();
        return string.concat(baseURI, Strings.toString(id), ".json");
    }
    function tokenURI(uint256 id) public view override returns (string memory) {
        _requireOwned(id);
        return previewURI(id);
    }

    function mint(uint256 quantity) external nonReentrant {
        if (quantity == 0 || quantity > MAX_BATCH || quantity > maxSupply - totalMinted)
            revert InvalidAmount();
        _minting = true;
        uint256 amount = quantity * tokenCost;
        uint256 beforeDead = IERC20(projectToken).balanceOf(DEAD);
        uint256 beforeUser = IERC20(projectToken).balanceOf(msg.sender);
        IERC20(projectToken).safeTransferFrom(msg.sender, DEAD, amount);
        if (IERC20(projectToken).balanceOf(DEAD) != beforeDead + amount
            || IERC20(projectToken).balanceOf(msg.sender) != beforeUser - amount)
            revert UnsupportedTransfer();
        uint256 first = totalMinted + 1;
        for (uint256 i; i < quantity; ++i) {
            ++totalMinted;
            _safeMint(msg.sender, totalMinted);
        }
        _minting = false;
        emit Minted(msg.sender, first, quantity, amount);
    }

    function recordFee(address asset, uint256 amount) external nonReentrant {
        if (msg.sender != hook) revert OnlyHook();
        if (!registeredAsset[asset]) revert UnsupportedAsset();
        if (_minting || totalMinted == 0 || amount == 0) revert InvalidAmount();
        uint256 next = recorded[asset] + amount;
        if (IERC20(asset).balanceOf(address(this)) < next - paid[asset])
            revert UnsupportedTransfer();
        recorded[asset] = next;
        // Division remainder stays unallocated: never roll old supply's dust into new NFTs.
        rewardIndex[asset] += Math.mulDiv(amount, PRECISION, totalMinted);
        emit FeeRecorded(asset, amount);
    }

    function claimable(address holder, address asset) public view returns (uint256) {
        if (!registeredAsset[asset]) revert UnsupportedAsset();
        uint256 delta = rewardIndex[asset] - _index[holder][asset];
        uint256 weight = holder == address(0) ? 0 : balanceOf(holder);
        return _earned[holder][asset] + Math.mulDiv(weight, delta, PRECISION)
            + (mulmod(weight, delta, PRECISION) + _fraction[holder][asset]) / PRECISION;
    }

    function _checkpoint(address holder) private {
        if (holder == address(0)) return;
        uint256 weight = balanceOf(holder);
        for (uint256 i; i < _assets.length; ++i) {
            address asset = _assets[i];
            uint256 index = rewardIndex[asset];
            uint256 delta = index - _index[holder][asset];
            uint256 fraction = mulmod(weight, delta, PRECISION) + _fraction[holder][asset];
            _earned[holder][asset] += Math.mulDiv(weight, delta, PRECISION) + fraction / PRECISION;
            _fraction[holder][asset] = fraction % PRECISION;
            _index[holder][asset] = index;
        }
    }

    function _update(address to, uint256 id, address auth) internal override returns (address from) {
        from = _ownerOf(id);
        if (_minting && from != address(0)) revert MintInProgress();
        if (to == address(0) || to == DEAD || to == address(this)) revert InvalidConfiguration();
        _checkpoint(from);
        if (to != from) _checkpoint(to);
        return super._update(to, id, auth);
    }

    function claim(address[] calldata selected) external nonReentrant {
        if (selected.length == 0 || selected.length > 5) revert InvalidAmount();
        _checkpoint(msg.sender);
        bool any;
        for (uint256 i; i < selected.length; ++i) {
            address asset = selected[i];
            if (!registeredAsset[asset]) revert UnsupportedAsset();
            for (uint256 j; j < i; ++j) if (selected[j] == asset) revert InvalidAmount();
            uint256 amount = _earned[msg.sender][asset];
            if (amount == 0) continue;
            any = true;
            _earned[msg.sender][asset] = 0;
            paid[asset] += amount;
            uint256 beforeVault = IERC20(asset).balanceOf(address(this));
            uint256 beforeHolder = IERC20(asset).balanceOf(msg.sender);
            IERC20(asset).safeTransfer(msg.sender, amount);
            if (IERC20(asset).balanceOf(address(this)) != beforeVault - amount
                || IERC20(asset).balanceOf(msg.sender) != beforeHolder + amount)
                revert UnsupportedTransfer();
            emit RewardClaimed(msg.sender, asset, amount);
        }
        if (!any) revert NoRewards();
    }
}

