/// @notice Per-project, individually upgradeable NFT reward custody.
/// @dev Owner authorizes upgrades ONLY; there is no owner claim or reward sweep.
contract PancakeV1NFTCollectionUpgradeable is ERC721Upgradeable, OwnableUpgradeable, UUPSUpgradeable {
    using SafeERC20 for IERC20;
    address public constant DEAD = 0x000000000000000000000000000000000000dEaD;
    uint256 public constant ORIGINAL_SUPPLY = 1_000_000_000 ether;
    uint256 public constant PRECISION = 1e27;
    uint256 public constant MAX_BATCH = 50;

    // Initial economic commitments remain unchanged by this implementation's upgrades.
    // UUPS governance is nevertheless trusted to approve only safe successors.
    address public projectToken;
    address public hook;
    uint256 public maxSupply;
    uint256 public tokenCost;
    uint256 public totalMinted;
    string public baseURI;
    address[] private _assets;
    mapping(address => bool) public registeredAsset;
    mapping(address => uint256) public rewardIndex;
    mapping(address => uint256) public recorded;
    mapping(address => uint256) public paid;
    mapping(address => mapping(address => uint256)) private _index;
    mapping(address => mapping(address => uint256)) private _earned;
    mapping(address => mapping(address => uint256)) private _fraction;
    bool private _minting;
    bool private _entered;

    error InvalidConfiguration();
    error OnlyHook();
    error InvalidAmount();
    error UnsupportedAsset();
    error UnsupportedTransfer();
    error NoRewards();
    error MintInProgress();
    error Reentered();
    event Minted(address indexed account, uint256 firstTokenId, uint256 quantity, uint256 projectBurned);
    event FeeRecorded(address indexed asset, uint256 amount);
    event RewardClaimed(address indexed holder, address indexed asset, uint256 amount);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    function initialize(address project_, address hook_, string memory name_, string memory symbol_,
        uint256 maximum_, uint256 cost_, string memory uri_, address[] memory assets_, address upgradeOwner)
        external initializer
    {
        bytes memory uri = bytes(uri_);
        bytes memory suffix = bytes("/metadata/");
        if (project_.code.length == 0 || hook_.code.length == 0 || upgradeOwner == address(0)
            || maximum_ == 0 || cost_ == 0 || maximum_ > (ORIGINAL_SUPPLY - 1) / cost_
            || bytes(name_).length == 0 || bytes(name_).length > 128
            || bytes(symbol_).length == 0 || bytes(symbol_).length > 32
            || uri.length < 18 || uri.length > 256 || assets_.length == 0 || assets_.length > 5)
            revert InvalidConfiguration();
        if (keccak256(_prefix(uri, 8)) != keccak256(bytes("https://"))
            && keccak256(_prefix(uri, 7)) != keccak256(bytes("ipfs://"))) revert InvalidConfiguration();
        for (uint256 i; i < suffix.length; ++i)
            if (uri[uri.length - suffix.length + i] != suffix[i]) revert InvalidConfiguration();
        for (uint256 i; i < uri.length; ++i)
            if (uint8(uri[i]) <= 32 || uri[i] == "?" || uri[i] == "#" || uri[i] == "\\")
                revert InvalidConfiguration();
        __ERC721_init(name_, symbol_);
        __Ownable_init(upgradeOwner);
        projectToken = project_;
        hook = hook_;
        maxSupply = maximum_;
        tokenCost = cost_;
        baseURI = uri_;
        for (uint256 i; i < assets_.length; ++i) {
            address asset = assets_[i];
            if (asset.code.length == 0 || asset == project_ || registeredAsset[asset])
                revert InvalidConfiguration();
            registeredAsset[asset] = true;
            _assets.push(asset);
        }
    }

    function _authorizeUpgrade(address) internal override onlyOwner {}
    modifier nonReentrant() {
        if (_entered) revert Reentered();
        _entered = true;
        _;
        _entered = false;
    }

    function _prefix(bytes memory value, uint256 size) private pure returns (bytes memory out) {
        out = new bytes(size);
        for (uint256 i; i < size; ++i) out[i] = value[i];
    }

    function assets() external view returns (address[] memory) { return _assets; }
    function rewardsActive() external view returns (bool) {
        if (_minting) revert MintInProgress();
        return totalMinted != 0;
    }
    function previewURI(uint256 id) public view returns (string memory) {
        if (id == 0 || id > maxSupply) revert InvalidAmount();
        return string.concat(baseURI, Strings.toString(id), ".json");
    }
    function tokenURI(uint256 id) public view override returns (string memory) {
        _requireOwned(id);
        return previewURI(id);
    }

    function mint(uint256 quantity) external nonReentrant {
        if (quantity == 0 || quantity > MAX_BATCH || quantity > maxSupply - totalMinted)
            revert InvalidAmount();
        _minting = true;
        uint256 amount = quantity * tokenCost;
        uint256 beforeDead = IERC20(projectToken).balanceOf(DEAD);
        uint256 beforeUser = IERC20(projectToken).balanceOf(msg.sender);
        IERC20(projectToken).safeTransferFrom(msg.sender, DEAD, amount);
        if (IERC20(projectToken).balanceOf(DEAD) != beforeDead + amount
            || IERC20(projectToken).balanceOf(msg.sender) != beforeUser - amount)
            revert UnsupportedTransfer();
        uint256 first = totalMinted + 1;
        for (uint256 i; i < quantity; ++i) {
            ++totalMinted;
            _safeMint(msg.sender, totalMinted);
        }
        _minting = false;
        emit Minted(msg.sender, first, quantity, amount);
    }

    function recordFee(address asset, uint256 amount) external nonReentrant {
        if (msg.sender != hook) revert OnlyHook();
        if (!registeredAsset[asset]) revert UnsupportedAsset();
        if (_minting || totalMinted == 0 || amount == 0) revert InvalidAmount();
        uint256 next = recorded[asset] + amount;
        if (IERC20(asset).balanceOf(address(this)) < next - paid[asset])
            revert UnsupportedTransfer();
        recorded[asset] = next;
        rewardIndex[asset] += Math.mulDiv(amount, PRECISION, totalMinted);
        emit FeeRecorded(asset, amount);
    }
    function claimable(address holder, address asset) public view returns (uint256) {
        if (!registeredAsset[asset]) revert UnsupportedAsset();
        uint256 delta = rewardIndex[asset] - _index[holder][asset];
        uint256 weight = holder == address(0) ? 0 : balanceOf(holder);
        return _earned[holder][asset] + Math.mulDiv(weight, delta, PRECISION)
            + (mulmod(weight, delta, PRECISION) + _fraction[holder][asset]) / PRECISION;
    }
    function _checkpoint(address holder) private {
        if (holder == address(0)) return;
        uint256 weight = balanceOf(holder);
        for (uint256 i; i < _assets.length; ++i) {
            address asset = _assets[i];
            uint256 index = rewardIndex[asset];
            uint256 delta = index - _index[holder][asset];
            uint256 fraction = mulmod(weight, delta, PRECISION) + _fraction[holder][asset];
            _earned[holder][asset] += Math.mulDiv(weight, delta, PRECISION) + fraction / PRECISION;
            _fraction[holder][asset] = fraction % PRECISION;
            _index[holder][asset] = index;
        }
    }
    function _update(address to, uint256 id, address auth) internal override returns (address from) {
        from = _ownerOf(id);
        if (_minting && from != address(0)) revert MintInProgress();
        if (to == address(0) || to == DEAD || to == address(this)) revert InvalidConfiguration();
        _checkpoint(from);
        if (to != from) _checkpoint(to);
        return super._update(to, id, auth);
    }
    function claim(address[] calldata selected) external nonReentrant {
        if (selected.length == 0 || selected.length > 5) revert InvalidAmount();
        _checkpoint(msg.sender);
        bool any;
        for (uint256 i; i < selected.length; ++i) {
            address asset = selected[i];
            if (!registeredAsset[asset]) revert UnsupportedAsset();
            for (uint256 j; j < i; ++j) if (selected[j] == asset) revert InvalidAmount();
            uint256 amount = _earned[msg.sender][asset];
            if (amount == 0) continue;
            any = true;
            _earned[msg.sender][asset] = 0;
            paid[asset] += amount;
            uint256 beforeVault = IERC20(asset).balanceOf(address(this));
            uint256 beforeHolder = IERC20(asset).balanceOf(msg.sender);
            IERC20(asset).safeTransfer(msg.sender, amount);
            if (IERC20(asset).balanceOf(address(this)) != beforeVault - amount
                || IERC20(asset).balanceOf(msg.sender) != beforeHolder + amount)
                revert UnsupportedTransfer();
            emit RewardClaimed(msg.sender, asset, amount);
        }
        if (!any) revert NoRewards();
    }
}

contracts/pancake-v1/PancakeV1NFTHook.so.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {PancakeV1Currency, PancakeV1BeforeSwapDelta, PancakeV1BalanceDelta,
    PancakeV1PoolKey, IPancakeV1Hooks, IPancakeV1CLPoolManager, IPancakeV1FeeReceiver,
    PancakeV1BalanceDeltaLib, PancakeV1BeforeSwapDeltaLib} from "./PancakeV1InfinityHookTypes.sol";
import {IPancakeV1FeeSettler} from "./PancakeV1InfinityHook.sol";
interface INFTGraph {
    function hook() external view returns (address);
    function factory() external view returns (address);
    function engine() external view returns (address);
    function verifyVault(address,uint8,address) external view returns (bool);
}
interface INFTActive { function rewardsActive() external view returns (bool); }

/// @notice New immutable hook; no policy changes, ownership transfer or legacy modes.
contract PancakeV1NFTHook is IPancakeV1Hooks {
    using PancakeV1BalanceDeltaLib for PancakeV1BalanceDelta;
    uint16 public constant HOOK_BITMAP = (1 << 6) | (1 << 7) | (1 << 10) | (1 << 11);
    uint16 public constant PROTOCOL_FEE_BPS = 30;
    uint8 public constant NFT_QUOTE = 5;
    address public immutable owner;
    IPancakeV1CLPoolManager public immutable poolManager;
    address public immutable protocolVault;
    address public registrar;
    address public attestor;
    bool public frozen;
    bool public adaptersAttested;
    mapping(address => bool) public trustedAdapter;
    event AdapterAttested(address indexed adapter,bytes32 runtimeHash);
    struct Policy { uint8 mode; uint16 feeBps; address destination; uint64 effectiveAt; }
    struct Pool { address project; address quote; uint160 graduationSqrtPriceX96; bool graduateWhenAbove; bool registered; }
    struct Pending { address project; address quote; address destination; uint256 protocolFee; uint256 modeFee; }
    mapping(address => Policy) private _policies;
    mapping(bytes32 => Pool) public pools;
    mapping(address => bool) public graduated;
    mapping(address => Pending) private _pending;
    error InvalidConfiguration();
    error Unauthorized();
    event PoolRegistered(bytes32 indexed poolId,address indexed project,address indexed quote,uint160 graduationSqrtPriceX96,bool graduateWhenAbove);
    event PolicyScheduled(address indexed project,uint64 indexed epoch,uint8 mode,uint16 feeBps,address destination,uint64 effectiveAt);
    event TokenGraduated(address indexed project,bytes32 indexed poolId,uint160 sqrtPriceX96);
    event ProtocolFeeAccrued(address indexed quote,address indexed destination,uint256 amount);
    event ModeFeeAccrued(address indexed project,address indexed asset,address indexed destination,uint256 amount);

    constructor(IPancakeV1CLPoolManager manager_,address protocol_) {
        if (address(manager_).code.length == 0 || protocol_.code.length == 0
            || manager_.vault().code.length == 0) revert InvalidConfiguration();
        owner = msg.sender; poolManager = manager_; protocolVault = protocol_;
    }
    function finalizeRelease(address engine_,address factory_) external {
        if (msg.sender != owner || frozen || !adaptersAttested) revert Unauthorized();
        if (INFTGraph(engine_).hook() != address(this) || INFTGraph(engine_).factory() != factory_
            || INFTGraph(factory_).hook() != address(this) || INFTGraph(factory_).engine() != engine_)
            revert InvalidConfiguration();
        if (INFTGraph(protocolVault).hook() != address(this)) revert InvalidConfiguration();
        registrar = engine_; attestor = factory_; frozen = true;
    }
    /// @notice Deployment-manifest attestation, deliberately NOT derived from
    /// untrusted sender getters. The deployer must verify these exact runtimes
    /// and constructor bindings before this irreversible authorization.
    function attestAdapters(address[] calldata adapters) external {
        if (msg.sender != owner || frozen || adaptersAttested || adapters.length == 0 || adapters.length > 5)
            revert Unauthorized();
        adaptersAttested = true;
        for (uint256 i; i < adapters.length; ++i) {
            address adapter = adapters[i];
            if (adapter.code.length == 0 || trustedAdapter[adapter]) revert InvalidConfiguration();
            trustedAdapter[adapter] = true;
            emit AdapterAttested(adapter,adapter.codehash);
        }
    }
    function getHooksRegistrationBitmap() external pure returns(uint16) { return HOOK_BITMAP; }
    function schedulePolicy(address project,uint8 mode,uint16 fee,address destination,uint64 effectiveAt)
        external returns(uint64) {
        if (!frozen || msg.sender != registrar) revert Unauthorized();
        if (mode != NFT_QUOTE || _policies[project].destination != address(0) || effectiveAt != 0
            || fee < 100 || fee > 1000 || fee % 100 != 0
            || !INFTGraph(attestor).verifyVault(project,mode,destination)) revert InvalidConfiguration();
        _policies[project] = Policy(mode,fee,destination,uint64(block.timestamp));
        emit PolicyScheduled(project,1,mode,fee,destination,uint64(block.timestamp));
        return 1;
    }
    function activePolicy(address project) public view returns(Policy memory) { return _policies[project]; }
    function effectiveFeeBps(address project) public view returns(uint16) {
        Policy memory p = _policies[project];
        if (p.destination == address(0)) revert InvalidConfiguration();
        return INFTActive(p.destination).rewardsActive() ? p.feeBps : 0;
    }
    function quoteInputFee(address project,uint256 amount) external view returns(uint256) {
        return amount * 30 / 10000 + amount * effectiveFeeBps(project) / 10000;
    }
    function poolId(PancakeV1PoolKey calldata key) public pure returns(bytes32) { return keccak256(abi.encode(key)); }
    function registerPool(PancakeV1PoolKey calldata key,address project,address quote,uint160 threshold,bool above) external {
        if (!frozen || msg.sender != registrar) revert Unauthorized();
        address c0 = PancakeV1Currency.unwrap(key.currency0);
        address c1 = PancakeV1Currency.unwrap(key.currency1);
        bytes32 id = poolId(key);
        if (pools[id].registered || _policies[project].destination == address(0) || threshold == 0
            || project == quote || project == address(0) || quote == address(0)
            || address(key.hooks) != address(this) || address(key.poolManager) != address(poolManager)
            || c0 >= c1 || !((c0 == project && c1 == quote) || (c1 == project && c0 == quote)))
            revert InvalidConfiguration();
        pools[id] = Pool(project,quote,threshold,above,true);
        emit PoolRegistered(id,project,quote,threshold,above);
    }
    function beforeSwap(address sender,PancakeV1PoolKey calldata key,IPancakeV1CLPoolManager.SwapParams calldata,bytes calldata)
        external view returns(bytes4,PancakeV1BeforeSwapDelta,uint24) {
        if (msg.sender != address(poolManager) || !frozen || !trustedAdapter[sender]) revert Unauthorized();
        Pool memory p = pools[poolId(key)];
        if (!p.registered) revert InvalidConfiguration();
        effectiveFeeBps(p.project); // Also blocks trades inside NFT receiver callbacks.
        return (this.beforeSwap.selector,PancakeV1BeforeSwapDeltaLib.toDelta(0,0),0);
    }
    function afterSwap(address sender,PancakeV1PoolKey calldata key,
        IPancakeV1CLPoolManager.SwapParams calldata params,PancakeV1BalanceDelta delta,bytes calldata)
        external returns(bytes4,int128) {
        if (msg.sender != address(poolManager) || !frozen || !trustedAdapter[sender]) revert Unauthorized();
        bytes32 id = poolId(key);
        Pool memory p = pools[id];
        if (!p.registered || sender.code.length == 0) revert InvalidConfiguration();
        if (!graduated[p.project]) {
            (uint160 price,,,) = poolManager.getSlot0(id);
            if (p.graduateWhenAbove ? price >= p.graduationSqrtPriceX96 : price <= p.graduationSqrtPriceX96) {
                graduated[p.project] = true;
                emit TokenGraduated(p.project,id,price);
            }
        }
        bool exactInput = params.amountSpecified < 0;
        bool quote0 = PancakeV1Currency.unwrap(key.currency0) == p.quote;
        bool quoteInput = params.zeroForOne == quote0;
        bool specified = quoteInput == exactInput;
        uint256 amount;
        if (specified) {
            amount = uint256(exactInput ? -params.amountSpecified : params.amountSpecified);
        } else {
            int256 q = quote0 ? int256(delta.amount0()) : int256(delta.amount1());
            amount = uint256(q < 0 ? -q : q);
        }
        Pending memory fees = Pending(p.project,p.quote,_policies[p.project].destination,
            amount * 30 / 10000,amount * effectiveFeeBps(p.project) / 10000);
        if (_pending[sender].project != address(0)) revert InvalidConfiguration();
        if (specified) _settle(sender,fees);
        else if (fees.protocolFee != 0 || fees.modeFee != 0) _pending[sender] = fees;
        return (this.afterSwap.selector,0);
    }
    function settleUnspecifiedFee() external {
        if (!trustedAdapter[msg.sender]) revert Unauthorized();
        Pending memory p = _pending[msg.sender];
        if (p.project == address(0)) return;
        delete _pending[msg.sender];
        _settle(msg.sender,p);
    }
    function _settle(address sender,Pending memory p) private {
        if (p.protocolFee != 0) {
            uint256 beforeBalance = IERC20(p.quote).balanceOf(protocolVault);
            IPancakeV1FeeSettler(sender).settleHookFee(p.quote,protocolVault,p.protocolFee);
            if (IERC20(p.quote).balanceOf(protocolVault) != beforeBalance + p.protocolFee)
                revert InvalidConfiguration();
            IPancakeV1FeeReceiver(protocolVault).recordFee(p.quote,p.protocolFee);
            emit ProtocolFeeAccrued(p.quote,protocolVault,p.protocolFee);
        }
        if (p.modeFee != 0) {
            uint256 beforeBalance = IERC20(p.quote).balanceOf(p.destination);
            IPancakeV1FeeSettler(sender).settleHookFee(p.quote,p.destination,p.modeFee);
            if (IERC20(p.quote).balanceOf(p.destination) != beforeBalance + p.modeFee)
                revert InvalidConfiguration();
            IPancakeV1FeeReceiver(p.destination).recordFee(p.quote,p.modeFee);
            emit ModeFeeAccrued(p.project,p.quote,p.destination,p.modeFee);
        }
    }
}

contracts/pancake-v1/PancakeV1NFTHookUpg.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {OwnableUpgradeable} from "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {PancakeV1Currency, PancakeV1BeforeSwapDelta, PancakeV1BalanceDelta,
    PancakeV1PoolKey, IPancakeV1Hooks, IPancakeV1CLPoolManager, IPancakeV1FeeReceiver,
    PancakeV1BalanceDeltaLib, PancakeV1BeforeSwapDeltaLib} from "./PancakeV1InfinityHookTypes.sol";
import {IPancakeV1FeeSettler} from "./PancakeV1InfinityHook.sol";

interface INFTUpgradeableGraph {
    function hook() external view returns (address);
    function factory() external view returns (address);
    function engine() external view returns (address);
    function verifyVault(address, uint8, address) external view returns (bool);
}
interface INFTUpgradeableActive { function rewardsActive() external view returns (bool); }
interface INFTSharedProtocolVault {
    function additionalHook(address) external view returns (bool);
    function recordFeeFromAdditionalHook(address, uint256) external;
}

/// @notice Stable-address UUPS hook for new NFT pools; old Infinity pools never use this hook.
/// @dev The proxy must be initialized atomically. Upgrade authority can alter financial
/// behavior; it must be governed and independently audited before live use.
contract PancakeV1NFTHookUpgradeable is Initializable, OwnableUpgradeable, UUPSUpgradeable, IPancakeV1Hooks {
    using PancakeV1BalanceDeltaLib for PancakeV1BalanceDelta;

    uint16 public constant HOOK_BITMAP = (1 << 6) | (1 << 7) | (1 << 10) | (1 << 11);
    uint16 public constant PROTOCOL_FEE_BPS = 30;
    uint8 public constant NFT_QUOTE = 5;

    struct Policy { uint8 mode; uint16 feeBps; address destination; uint64 effectiveAt; }
    struct Pool { address project; address quote; uint160 graduationSqrtPriceX96; bool graduateWhenAbove; bool registered; }
    struct Pending { address project; address quote; address destination; uint256 protocolFee; uint256 modeFee; }
    struct Layout {
        IPancakeV1CLPoolManager poolManager;
        address protocolVault;
        address registrar;
        address attestor;
        bool frozen;
        bool adaptersAttested;
        mapping(address => bool) trustedAdapter;
        mapping(address => Policy) policies;
        mapping(bytes32 => Pool) pools;
        mapping(address => bool) graduated;
        mapping(address => Pending) pending;
    }
    // ERC-7201-style isolated storage; existing upgrades must retain this slot and layout.
    bytes32 private constant STORAGE_SLOT =
        bytes32(uint256(keccak256(abi.encode(uint256(keccak256("pair.infinity.nft.hook.storage")) - 1))) & ~uint256(0xff));
    function _layout() private pure returns (Layout storage s) {
        bytes32 slot = STORAGE_SLOT;
        assembly { s.slot := slot }
    }

    error InvalidConfiguration();
    error Unauthorized();
    event AdapterAttested(address indexed adapter, bytes32 runtimeHash);
    event PoolRegistered(bytes32 indexed poolId,address indexed project,address indexed quote,uint160 graduationSqrtPriceX96,bool graduateWhenAbove);
    event PolicyScheduled(address indexed project,uint64 indexed epoch,uint8 mode,uint16 feeBps,address destination,uint64 effectiveAt);
    event TokenGraduated(address indexed project,bytes32 indexed poolId,uint160 sqrtPriceX96);
    event ProtocolFeeAccrued(address indexed quote,address indexed destination,uint256 amount);
    event ModeFeeAccrued(address indexed project,address indexed asset,address indexed destination,uint256 amount);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    function initialize(address owner_, IPancakeV1CLPoolManager manager_, address protocol_) external initializer {
        if (owner_ == address(0) || address(manager_).code.length == 0
            || protocol_.code.length == 0 || manager_.vault().code.length == 0) revert InvalidConfiguration();
        __Ownable_init(owner_);
        Layout storage s = _layout();
        s.poolManager = manager_;
        s.protocolVault = protocol_;
    }
    function _authorizeUpgrade(address) internal override onlyOwner {}
    function poolManager() external view returns (IPancakeV1CLPoolManager) { return _layout().poolManager; }
    function protocolVault() external view returns (address) { return _layout().protocolVault; }
    function registrar() external view returns (address) { return _layout().registrar; }
    function attestor() external view returns (address) { return _layout().attestor; }
    function frozen() external view returns (bool) { return _layout().frozen; }
    function adaptersAttested() external view returns (bool) { return _layout().adaptersAttested; }
    function trustedAdapter(address a) external view returns (bool) { return _layout().trustedAdapter[a]; }
    function pools(bytes32 id) external view returns (Pool memory) { return _layout().pools[id]; }
    function graduated(address project) external view returns (bool) { return _layout().graduated[project]; }
    function getHooksRegistrationBitmap() external pure returns(uint16) { return HOOK_BITMAP; }

    function finalizeRelease(address engine_,address factory_) external onlyOwner {
        Layout storage s = _layout();
        if (s.frozen || !s.adaptersAttested) revert Unauthorized();
        if (engine_.code.length == 0 || factory_.code.length == 0
            || INFTUpgradeableGraph(engine_).hook() != address(this)
            || INFTUpgradeableGraph(engine_).factory() != factory_
            || INFTUpgradeableGraph(factory_).hook() != address(this)
            || INFTUpgradeableGraph(factory_).engine() != engine_
            || !INFTSharedProtocolVault(s.protocolVault).additionalHook(address(this)))
            revert InvalidConfiguration();
        s.registrar = engine_;
        s.attestor = factory_;
        s.frozen = true;
    }
    /// @notice Once-only attestation of reviewed adapters, including their actual code hashes.
    function attestAdapters(address[] calldata adapters) external onlyOwner {
        Layout storage s = _layout();
        if (s.frozen || s.adaptersAttested || adapters.length == 0 || adapters.length > 5)
            revert Unauthorized();
        s.adaptersAttested = true;
        for (uint256 i; i < adapters.length; ++i) {
            address adapter = adapters[i];
            if (adapter.code.length == 0 || s.trustedAdapter[adapter]) revert InvalidConfiguration();
            s.trustedAdapter[adapter] = true;
            emit AdapterAttested(adapter, adapter.codehash);
        }
    }
    function schedulePolicy(address project,uint8 mode,uint16 fee,address destination,uint64 effectiveAt)
        external returns(uint64) {
        Layout storage s = _layout();
        if (!s.frozen || msg.sender != s.registrar) revert Unauthorized();
        if (mode != NFT_QUOTE || s.policies[project].destination != address(0) || effectiveAt != 0
            || fee < 100 || fee > 1000 || fee % 100 != 0 || destination.code.length == 0
            || !INFTUpgradeableGraph(s.attestor).verifyVault(project, mode, destination))
            revert InvalidConfiguration();
        s.policies[project] = Policy(mode,fee,destination,uint64(block.timestamp));
        emit PolicyScheduled(project,1,mode,fee,destination,uint64(block.timestamp));
        return 1;
    }
    function activePolicy(address project) public view returns(Policy memory) {
        return _layout().policies[project];
    }
    function effectiveFeeBps(address project) public view returns(uint16) {
        Policy memory p = _layout().policies[project];
        if (p.destination == address(0)) revert InvalidConfiguration();
        return INFTUpgradeableActive(p.destination).rewardsActive() ? p.feeBps : 0;
    }
    function quoteInputFee(address project,uint256 amount) external view returns(uint256) {
        return amount * PROTOCOL_FEE_BPS / 10000 + amount * effectiveFeeBps(project) / 10000;
    }
    function poolId(PancakeV1PoolKey calldata key) public pure returns(bytes32) { return keccak256(abi.encode(key)); }
    function registerPool(PancakeV1PoolKey calldata key,address project,address quote,uint160 threshold,bool above) external {
        Layout storage s = _layout();
        if (!s.frozen || msg.sender != s.registrar) revert Unauthorized();
        address c0 = PancakeV1Currency.unwrap(key.currency0);
        address c1 = PancakeV1Currency.unwrap(key.currency1);
        bytes32 id = poolId(key);
        if (s.pools[id].registered || s.policies[project].destination == address(0) || threshold == 0
            || project == quote || project == address(0) || quote == address(0)
            || address(key.hooks) != address(this) || address(key.poolManager) != address(s.poolManager)
            || c0 >= c1 || !((c0 == project && c1 == quote) || (c1 == project && c0 == quote)))
            revert InvalidConfiguration();
        s.pools[id] = Pool(project,quote,threshold,above,true);
        emit PoolRegistered(id,project,quote,threshold,above);
    }
    function beforeSwap(address sender,PancakeV1PoolKey calldata key,IPancakeV1CLPoolManager.SwapParams calldata,bytes calldata)
        external view returns(bytes4,PancakeV1BeforeSwapDelta,uint24) {
        Layout storage s = _layout();
        if (msg.sender != address(s.poolManager) || !s.frozen || !s.trustedAdapter[sender]) revert Unauthorized();
        Pool memory p = s.pools[poolId(key)];
        if (!p.registered) revert InvalidConfiguration();
        effectiveFeeBps(p.project);
        return (this.beforeSwap.selector,PancakeV1BeforeSwapDeltaLib.toDelta(0,0),0);
    }
    function afterSwap(address sender,PancakeV1PoolKey calldata key,
        IPancakeV1CLPoolManager.SwapParams calldata params,PancakeV1BalanceDelta delta,bytes calldata)
        external returns(bytes4,int128) {
        Layout storage s = _layout();
        if (msg.sender != address(s.poolManager) || !s.frozen || !s.trustedAdapter[sender]) revert Unauthorized();
        bytes32 id = poolId(key);
        Pool memory p = s.pools[id];
        if (!p.registered || sender.code.length == 0) revert InvalidConfiguration();
        if (!s.graduated[p.project]) {
            (uint160 price,,,) = s.poolManager.getSlot0(id);
            if (p.graduateWhenAbove ? price >= p.graduationSqrtPriceX96 : price <= p.graduationSqrtPriceX96) {
                s.graduated[p.project] = true;
                emit TokenGraduated(p.project,id,price);
            }
        }
        bool exactInput = params.amountSpecified < 0;
        bool quote0 = PancakeV1Currency.unwrap(key.currency0) == p.quote;
        bool quoteInput = params.zeroForOne == quote0;
        bool specified = quoteInput == exactInput;
        uint256 amount;
        if (specified) amount = uint256(exactInput ? -params.amountSpecified : params.amountSpecified);
        else {
            int256 q = quote0 ? int256(delta.amount0()) : int256(delta.amount1());
            amount = uint256(q < 0 ? -q : q);
        }
        Pending memory fees = Pending(p.project,p.quote,s.policies[p.project].destination,
            amount * PROTOCOL_FEE_BPS / 10000,amount * effectiveFeeBps(p.project) / 10000);
        if (s.pending[sender].project != address(0)) revert InvalidConfiguration();
        if (specified) _settle(sender,fees);
        else if (fees.protocolFee != 0 || fees.modeFee != 0) s.pending[sender] = fees;
        return (this.afterSwap.selector,0);
    }
    function settleUnspecifiedFee() external {
        Layout storage s = _layout();
        if (!s.trustedAdapter[msg.sender]) revert Unauthorized();
        Pending memory p = s.pending[msg.sender];
        if (p.project == address(0)) return;
        delete s.pending[msg.sender];
        _settle(msg.sender,p);
    }
    function _settle(address sender,Pending memory p) private {
        address vault = _layout().protocolVault;
        if (p.protocolFee != 0) {
            uint256 beforeBalance = IERC20(p.quote).balanceOf(vault);
            IPancakeV1FeeSettler(sender).settleHookFee(p.quote,vault,p.protocolFee);
            if (IERC20(p.quote).balanceOf(vault) != beforeBalance + p.protocolFee)
                revert InvalidConfiguration();
            INFTSharedProtocolVault(vault).recordFeeFromAdditionalHook(p.quote,p.protocolFee);
            emit ProtocolFeeAccrued(p.quote,vault,p.protocolFee);
        }
        if (p.modeFee != 0) {
            uint256 beforeBalance = IERC20(p.quote).balanceOf(p.destination);
            IPancakeV1FeeSettler(sender).settleHookFee(p.quote,p.destination,p.modeFee);
            if (IERC20(p.quote).balanceOf(p.destination) != beforeBalance + p.modeFee)
                revert InvalidConfiguration();
            IPancakeV1FeeReceiver(p.destination).recordFee(p.quote,p.modeFee);
            emit ModeFeeAccrued(p.project,p.quote,p.destination,p.modeFee);
        }
    }
}

contracts/pancake-v1/PancakeV1NFTProxyFa.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {PancakeV1InfinityCreationDeployers} from "./PancakeV1InfinityCreationDeployers.sol";
import {PancakeV1NFTCollectionProxyDeployer} from "./PancakeV1NFTCollectionProxyDeployer.sol";

interface INFTProxyFactoryModule {
    function factory() external view returns (address);
    function hook() external view returns (address);
    function launchpad() external view returns (address);
}

/// @notice NFT factory for the EXISTING Infinity proxy entrypoint.
/// @dev Module != launchpad. Immutable collection deployer is bound to this factory.
contract PancakeV1NFTProxyFactory {
    address public immutable admin;
    address public immutable hook;
    PancakeV1InfinityCreationDeployers public immutable creationDeployers;
    PancakeV1NFTCollectionProxyDeployer public immutable collectionDeployer;
    address public engine;
    mapping(address => address) public collectionOf;
    struct Identity { address creator; string name; string symbol; string metadataURI; bytes32 metadataHash; }
    event NFTCollectionCreated(address indexed projectToken, address indexed collection, address indexed creator);
    error InvalidConfiguration();

    constructor(address hook_, PancakeV1InfinityCreationDeployers deployers_,
        PancakeV1NFTCollectionProxyDeployer collectionDeployer_)
    {
        if (hook_.code.length == 0 || address(deployers_).code.length == 0
            || deployers_.admin() != msg.sender || address(collectionDeployer_).code.length == 0
            || collectionDeployer_.factory() != address(this) || collectionDeployer_.hook() != hook_)
            revert InvalidConfiguration();
        admin = msg.sender;
        hook = hook_;
        creationDeployers = deployers_;
        collectionDeployer = collectionDeployer_;
    }
    function bindEngine(address module) external {
        if (msg.sender != admin || engine != address(0) || module.code.length == 0
            || INFTProxyFactoryModule(module).factory() != address(this)
            || INFTProxyFactoryModule(module).hook() != hook
            || INFTProxyFactoryModule(module).launchpad() != creationDeployers.tokenLaunchpad()
            || creationDeployers.engine() != address(this)) revert InvalidConfiguration();
        engine = module;
    }
    function verifyVault(address project, uint8 mode, address destination) external view returns (bool) {
        return mode == 5 && destination != address(0) && collectionOf[project] == destination;
    }
    function tokenLaunchpad() external view returns (address) { return creationDeployers.tokenLaunchpad(); }
    function positionManager() external view returns (address) { return creationDeployers.positionManager(); }
    function vault() external view returns (address) { return creationDeployers.vault(); }
    function _lockSalt(Identity calldata i) private pure returns (bytes32) {
        return keccak256(abi.encode(keccak256("PANCAKE_V1_INFINITY_LOCK"),
            i.creator, i.name, i.symbol, i.metadataURI, i.metadataHash));
    }
    function _tokenSalt(address creator, bytes32 salt) private pure returns (bytes32) {
        return keccak256(abi.encode(keccak256("PANCAKE_V1_INFINITY_TOKEN"), creator, salt));
    }
    function predictStandard(Identity calldata i, bytes32 salt, uint256 protection)
        public view returns (address token, address lock)
    {
        if (protection != 0 || engine == address(0)) revert InvalidConfiguration();
        lock = creationDeployers.predictLock(_lockSalt(i));
        token = creationDeployers.predictStandard(_tokenSalt(i.creator, salt), i.name, i.symbol,
            i.metadataURI, i.metadataHash, lock, i.creator, creationDeployers.tokenLaunchpad(), 0);
    }
    function deploy(Identity calldata i, bytes32 salt, bytes calldata configuration, address[] calldata quotes)
        external returns (address token, address lock, address collection)
    {
        if (msg.sender != engine || engine == address(0)) revert InvalidConfiguration();
        lock = creationDeployers.lock(_lockSalt(i));
        token = creationDeployers.standard(_tokenSalt(i.creator, salt), i.name, i.symbol,
            i.metadataURI, i.metadataHash, lock, i.creator, creationDeployers.tokenLaunchpad(), 0);
        (string memory name, string memory symbol, uint256 maximum, uint256 cost, string memory uri) =
            abi.decode(configuration, (string, string, uint256, uint256, string));
        collection = collectionDeployer.deploy(token, name, symbol, maximum, cost, uri, quotes);
        collectionOf[token] = collection;
        emit NFTCollectionCreated(token, collection, i.creator);
    }
}

